// Actual curve degrees: formal-21
entries.dedekindplaces=["Dedekind chart primes and actual valuation rings", "A nontrivial valuation ring A containing a Dedekind chart R in its actual fraction field K equals the actual adic valuation ring of a unique height-one prime p.", "Construct the nonzero prime by contracting the actual maximal ideal of A. A zero contraction would invert every nonzero denominator and force A=K. The actual localization inclusion and equality are proved, not supplied.", ["An actual Dedekind domain R and its actual fraction field K.", "A is a nontrivial valuation subring of K containing the actual image of R."], [["Invert unit denominators", "Fractions with unit denominators stay in A."], ["Nonzero center", "A zero contraction would make the valuation trivial."], ["Unique prime", "Construct the center prime and identify its actual adic subring."]]];
entries.chartcover=["Finite/infinity charts cover every valuation", "Every ground-field valuation ring in L contains the actual integral closure of k[t], or the actual integral closure of the infinity DVR of k(t).", "Split according to regularity of t. Polynomial valuations handle the finite chart; numerator/denominator degree comparison handles a pole. Integral closedness then includes the actual normalization ring. Coverage is not an input.", ["Any field k, an actual extension k(t)→L, and compatible ground-field structure.", "A valuation subring A of L containing all ground-field constants."], [["Constant valuation", "Every nonzero constant and its inverse are regular."], ["Integrality", "Integral elements over a contained ring belong to the valuation ring."], ["Parameter pole", "Degree comparison includes the actual infinity DVR."], ["Coverage", "The two charts cover all actual valuations."]]];
entries.chartclass=["Finite/infinity primes: exhaustive and disjoint", "Every nontrivial ground-field valuation ring in a finite separable L/k(t) comes from exactly one prime of exactly one of the two actual normalization charts.", "The parameter t is regular at finite primes. At infinity, 1/t lies in the contracted maximal ideal, so t has a pole. This proves disjointness; coverage and unique chart centers prove completeness.", ["An actual finite separable extension L/k(t), in arbitrary characteristic.", "A nontrivial valuation subring containing the actual ground field k."], [["Finite places", "The parameter is regular in every finite-prime valuation ring."], ["Infinity places", "The contracted maximal ideal forces a parameter pole."], ["Disjointness", "Primes of the two charts define distinct valuation rings."], ["Exhaustive uniqueness", "Coverage and unique centers yield exactly one prime."]]];
entries.adicorders=["Adic and actual DVR orders agree", "The normalized adic order at a Dedekind chart prime equals numerator order minus denominator order in its actual valuation ring.", "Actual uniformizers and ideal multiplicities fix the normalization. Regular equations are handled first, then arbitrary rational functions including poles. Equality of valuation subrings alone is not used as a normalization argument.", ["An actual Dedekind chart, fraction field and height-one prime p.", "A nonzero rational function in the actual function field."], [["Regular equations", "Principal-ideal multiplicity equals additive DVR order."], ["Poles included", "Any fraction has numerator order minus denominator order."], ["Chart primes", "Uniformizer value exp(−1) fixes the normalization."]]];
entries.curvechartplaces=["Actual curve points and two-chart primes correspond", "With a compatible finite separable parameter, every actual codimension-one closed point of the proper normal curve corresponds to exactly one finite or infinity normalization prime.", "Construct actual points from Hartshorne I.6 centers. Exhaustive classification supplies every point; disjointness prevents duplicates. No point list or point bijection is an input. Parameter existence remains separately open.", ["An actual proper normal integral locally Noetherian curve C of dimension≤1.", "A given compatible finite separable parameter k(t)→K(C). Constructing the parameter from the actual curve remains open."], [["Actual centers", "Each chart-prime valuation has an actual closed center on C."], ["Same valuation", "The actual center stalk gives the chart valuation."], ["Every point exactly once", "Exhaustive disjoint classification and unique centers give the bijection."]]];
entries.curveprincipal=["Actual complete curve: principal degree zero", "Over an algebraically closed field of arbitrary characteristic, with a compatible finite separable parameter, the actual proper normal curve has a finitely supported principal divisor with coefficients ordₚ(a) and total degree zero.", "Transport the actual chart divisors through the constructed exhaustive point bijection, prove each coefficient is the actual curve-stalk order, and transport the norm product formula. Degree zero is not an input. Parameter construction and the full pullback-degree formula remain open.", ["An actual proper normal integral locally Noetherian curve C of dimension≤1.", "A given compatible finite separable parameter k(t)→K(C). Constructing the parameter from the actual curve remains open.", "An algebraically closed ground field k, in arbitrary characteristic."], [["Actual local orders", "A chart-prime order equals the actual center stalk order."], ["Every closed-point coefficient", "Construct finite support and prove each coefficient is ordₚ(a)."], ["Total degree zero", "The point bijection transports the function-field product formula."]]];
entries.cartierprincipal=["Cartier degree is invariant under principal moving", "Multiplying every local Cartier equation on the actual proper normal curve by one nonzero rational function leaves its total local-order degree unchanged.", "Prove pointwise that the new divisor is the original divisor plus the actual div(a), then apply principal degree zero. This moving-degree gap is closed. Parameter existence, ambient curve normalization, real intersection and relative ample positivity still require integration.", ["An actual proper normal integral locally Noetherian curve C of dimension≤1.", "A given compatible finite separable parameter k(t)→K(C). Constructing the parameter from the actual curve remains open.", "An algebraically closed field k of arbitrary characteristic; actual affine Cartier equations and unit transitions."], [["All actual Scheme points", "Embed the closed-point divisor into the curve, with zero at other points."], ["Actual divisor identity", "Multiplication by a adds ordₚ(a) to every coefficient."], ["Degree unchanged", "The actual principal divisor has degree zero."]]];

entries.curveplaces[2]='The actual curve-point/valuation bijection, exhaustive disjoint finite/infinity classification, actual local orders and principal total-sum transport are now proved with an explicit compatible finite separable parameter. Constructing that parameter from the actual curve remains open.';
entries.curveorders[2]='Actual stalk isomorphisms preserve all rational orders. The correspondence is now connected to every finite/infinity prime and transports principal degree zero with an explicit compatible finite separable parameter.';
entries.functionproduct[2]='Actual integral closures, norm identities, infinity residues and degree-one k-weights are proved. Exhaustive disjoint classification now connects the order sum to an actual proper normal curve. A compatible finite separable parameter is still explicit; its existence must not be hidden.';
entries.projection[2]='Exhaustive disjoint finite/infinity classification, actual closed-point sums, normalized DVR orders and Cartier principal-move invariance are proved with an explicit compatible finite separable parameter. Parameter existence, global pullback degree, curve normalization and point-image zero remain open. The full projection formula is not proved.';
entries.projection[3][2]='Open: construct a compatible finite separable parameter from the actual curve; global pullback degree, curve normalization and point-image zero.';
entries.projection[4].splice(entries.projection[4].length-1,0,['Actual curve principal divisor: verified','Coefficients are actual local orders at every closed point; the total degree is zero with explicit parameter hypotheses.'],['Principal moving: verified','Multiplying Cartier local equations by a global rational function preserves degree.']);
entries.projection[4][entries.projection[4].length-1]=['Remaining geometry: open','Construct the compatible separable parameter, then integrate global pullback degree, normalization and point-image zero.'];
entries.intersection[2]='Actual Cartier restriction, effectivity positivity, real effective decompositions, all point/valuation correspondences, actual principal degree zero and principal-move invariance are proved. The last two explicitly require a compatible finite separable parameter. Parameter construction, normalization, full presentation-independent real intersection and geometric relative ample positivity remain open.';
entries.intersection[3][1]='Principal moving is degree-invariant. Compatible parameter construction, normalization, the real intersection interface and geometric relative ample positivity still require integration.';

// No extra curve parameter inputs: formal-22
entries.separatingparameter=["Separating parameter in arbitrary characteristic", "An essentially finite-type field L of transcendence degree one over a perfect k admits a compatible k(t) embedding with L/k(t) finite and separable.", "Construct a one-element separating transcendence basis and an actual rational-function embedding. Perfectness is required only for the constant field k, never for k(t).", ["A perfect ground field k and an actual essentially finite-type field L/k.", "trdegₖ L=1; the adjacent geometric node derives these inputs for actual curves."], [["One-element basis", "Transcendence degree one yields an actual transcendental element."], ["Actual embedding", "Construct k(t)→L and transfer finiteness and separability."]]];
entries.affinecurvefield=["Affine curve function fields: generation and dimension", "The actual fraction field L of a non-field finite-type k-domain R of dimension≤1 is essentially finite type with trdegₖ L=1.", "Noether normalization constructs a polynomial subring. Lying over and maximal contraction bound its variable count by one; the non-field condition excludes zero variables. Transfer transcendence degree through the actual fraction localization.", ["A non-field finite-type k-domain R of Krull dimension≤1.", "L is its actual fraction field, with compatible constants."], [["Integral subring dimension", "Lying over and maximal contraction preserve the dimension bound."], ["Exactly one variable", "Noether normalization has exactly one variable."], ["Actual fraction field", "Fraction localization gives essential finite type and transcendence degree one."]]];
entries.curveparameter=["Actual curves: construct the separating parameter", "The function field of an actual finite-type one-dimensional integral curve automatically admits a compatible finite separable k(t) parameter.", "Choose an actual codimension-one point and affine neighborhood from dimension. Prove the chart is finite type, dimension≤1 and not a field; verify the constants square and fraction field, then construct the parameter.", ["An actual one-dimensional integral Scheme C with finite-type b:C→Spec k.", "An algebraically closed k of arbitrary characteristic; constants come from the actual generic-stalk structure map."], [["Actual chart", "A genuine codimension-one point proves the chart is not a field."], ["Generic constants", "Affine constants agree with actual function-field constants."], ["Field properties", "Derive generation and transcendence degree from Scheme geometry."], ["No parameter input", "Construct a compatible finite separable parameter from the actual curve."]]];
entries.curveproductcomplete=["Complete normal curve product formula: no parameter input", "Every nonzero rational function on an actual complete normal integral curve over an algebraically closed field has finite principal support, actual coefficients ordₚ(a), and Σₚ ordₚ(a)=0.", "Construct the separating parameter from the actual curve, then apply Hartshorne I.6 unique centers, exhaustive disjoint places and actual local-order transport. Degree zero, parameter existence and a place list are not inputs.", ["An actual one-dimensional integral Scheme C with finite-type b:C→Spec k.", "An algebraically closed k of arbitrary characteristic; constants come from the actual generic-stalk structure map.", "C is proper and locally Noetherian, with integrally closed actual stalks; a∈K(C)ˣ."], [["Geometry to product formula", "Construct the parameter, then transport actual local orders and principal degree zero."]]];
entries.cartierdegreecomplete=["Complete-curve Cartier moving: no parameter input", "Multiplying actual Cartier local equations by a∈K(C)ˣ preserves degree on a complete normal curve, with no extra parameter or compactness input.", "Derive compactness from properness and the parameter from finite-type curve geometry, then use the actual pointwise principal-divisor identity and degree zero. Ambient normalization, full pullback degree and geometric ample positivity remain open.", ["An actual one-dimensional integral Scheme C with finite-type b:C→Spec k.", "An algebraically closed k of arbitrary characteristic; constants come from the actual generic-stalk structure map.", "C is proper, locally Noetherian and normal; actual CartierAtlas equations and unit transitions."], [["Moving preserves degree", "Construct the parameter, derive compactness and prove actual Cartier degree invariance."]]];

entries.projection[2]='The separating parameter now follows from actual finite-type one-dimensional Scheme geometry. Actual principal degree zero and Cartier principal-move invariance need no parameter input. Global pullback degree, curve normalization and point-image zero remain open; the full projection formula is unfinished.';
entries.projection[3][2]='Open: global pullback degree, ambient curve normalization and point-image zero.';
entries.projection[4][entries.projection[4].length-1]=['Remaining geometry: open','Integrate global pullback degree, normalization and point-image zero. The actual curve parameter is constructed.'];
entries.intersection[2]='The actual complete normal curve parameter, principal degree zero and Cartier principal-move invariance are derived from Scheme geometry. Ambient normalization, presentation-independent real intersection and geometric relative ample positivity remain open. The full negativity lemma is unfinished.';
entries.intersection[3][1]='Actual curve parameters and principal-move invariance are proved. Ambient normalization, real intersection and geometric relative ample positivity remain open.';
for(const id of ['curvechartplaces','curveprincipal','cartierprincipal']) {
  entries[id][2]+=' Actual-curve parameter existence is now proved at curveparameter; the new final product and Cartier-moving nodes have no parameter input.';
  entries[id][3]=entries[id][3].map(t=>t.replace('Constructing the parameter from the actual curve remains open.','The actual curve parameter is constructed at curveparameter.'));
}

entries.curvechartplaces[2]='This auxiliary theorem uses an explicit parameter to construct the exhaustive disjoint prime/actual-point bijection. Parameter existence is proved from actual finite-type one-dimensional Scheme geometry; see curveproductcomplete for the final theorem without a parameter input.';
entries.curveprincipal[2]='This parameterized auxiliary identifies actual local orders and principal degree zero. The parameter is now constructed from actual curve geometry; curveproductcomplete has no parameter input. Global pullback degree remains open.';
entries.cartierprincipal[2]='The actual pointwise principal-divisor identity and degree zero prove moving invariance. Parameter existence is complete; cartierdegreecomplete needs neither a parameter nor a compactness input.';
entries.curveplaces[2]='Hartshorne I.6 actual unique centers and the point/valuation bijection are proved. Exhaustive chart places, local orders and total sums are connected. The compatible separating parameter is constructed from actual finite-type curve geometry.';
entries.functionproduct[2]='Actual integral closures, norms, infinity residues and weights are proved and transported through the exhaustive valuation classification. The actual finite-type curve supplies the separating parameter; the final complete-curve product formula has no parameter input.';

// Actual proper curve pullback degree: formal-23
entries.affineorders=["Affine primes and actual stalk orders", "Actual normal-curve affine coordinates are Dedekind, and normalized prime orders equal actual Scheme stalk orders.", "Construct local-ring isomorphisms inside the common function field from actual localization uniqueness. Order compatibility is proved.", ["An integral locally Noetherian Scheme of dimension≤1 with integrally closed stalks.", "An actual nonempty affine open U."], [["Affine primes and actual stalk orders", "Construct local-ring isomorphisms inside the common function field from actual localization uniqueness. Order compatibility is proved."]]];
entries.finiteorders=["Weighted local degree for finite curve maps", "For an actual finite dominant normal-curve map, Σₓ ordₓ(f*a)[κ(x):κ(y)]=[K(X):K(Y)]ordᵧ(a).", "Actual section and generic maps construct compatible field towers. Finiteness, torsion-freeness and flatness are derived; separability is not required.", ["Actual finite dominant f:X→Y; normal integral locally Noetherian curves of dimension≤1.", "An actual affine neighborhood of y and nonzero rational a."], [["Weighted local degree for finite curve maps", "Actual section and generic maps construct compatible field towers. Finiteness, torsion-freeness and flatness are derived; separability is not required."]]];
entries.fiberprimes=["Actual fiber points and chart primes", "Chart primes over p correspond bijectively to every actual point x with f(x)=y.", "The inverse maps use actual fromSpec and primeIdealOf. The section-map square proves lying over; no fiber list is supplied.", ["An actual affine morphism and target affine open U.", "An actual prime p of Γ(Y,U)."], [["Actual fiber points and chart primes", "The inverse maps use actual fromSpec and primeIdealOf. The section-map square proves lying over; no fiber list is supplied."]]];
entries.closedresidue=["Algebraically closed base: residue degree one", "Every actual closed-point fiber prime of a finite dominant normal-curve map has [κ(x):κ(y)]=1.", "Construct constants and scalar towers from the actual Scheme structure maps. Finite type and Zariski’s lemma compute residue degrees in arbitrary characteristic.", ["An algebraically closed k of arbitrary characteristic and finite-type Y→Spec k.", "An actual finite dominant normal-curve map and closed-point fiber."], [["Algebraically closed base: residue degree one", "Construct constants and scalar towers from the actual Scheme structure maps. Finite type and Zariski’s lemma compute residue degrees in arbitrary characteristic."]]];
entries.fiberorders=["Actual fibers: count with multiplicity", "For actual finite dominant normal-curve maps, Σ_{f(x)=y} ordₓ(f*a)=[K(X):K(Y)]ordᵧ(a).", "Sum over every actual fiber point. Codimension one and residue degree one are proved. Purely inseparable maps are included.", ["An algebraically closed ground field of arbitrary characteristic.", "An actual finite dominant normal-curve map, closed y and nonzero rational a."], [["Actual fibers: count with multiplicity", "Sum over every actual fiber point. Codimension one and residue degree one are proved. Purely inseparable maps are included."]]];
entries.finitecurvepoints=["Finite curve maps preserve closed points", "Actual finite dominant normal-curve maps send codimension-one points to codimension-one points; nonempty affine opens have nonempty preimages.", "Contract actual height-one primes in the integral affine-chart extension. Point identification and lying over come from Scheme geometry.", ["An actual finite dominant normal integral curve map of dimension≤1.", "An actual codimension-one point x."], [["Finite curve maps preserve closed points", "Contract actual height-one primes in the integral affine-chart extension. Point identification and lying over come from Scheme geometry."]]];
entries.cartierfiber=["Actual Cartier pullback fiber coefficients", "Construct actual B=f*D and prove Σ_{f(x)=y}coeffₓ(B)=[K(X):K(Y)]coeffᵧ(D) for each closed y.", "The output includes actual pullback charts and equations, not merely existence of a divisor of equal degree. Cartier coefficients are actual stalk orders.", ["An actual finite dominant normal-curve map over an algebraically closed field of arbitrary characteristic.", "Actual Cartier equations and unit transitions."], [["Actual Cartier pullback fiber coefficients", "The output includes actual pullback charts and equations, not merely existence of a divisor of equal degree. Cartier coefficients are actual stalk orders."]]];
entries.cartierglobal=["Global Cartier degree: actual finite pullback", "Construct actual B=f*D on compact normal integral curves and prove deg(B)=[K(X):K(Y)]deg(D).", "First prove actual Cartier push-pull coefficients, then sum finite support. Neither global projection nor local order compatibility is assumed.", ["An actual finite dominant normal-curve map of dimension≤1 over an algebraically closed field.", "Compact source and target; actual CartierAtlas D."], [["Global Cartier degree: actual finite pullback", "First prove actual Cartier push-pull coefficients, then sum finite support. Neither global projection nor local order compatibility is assumed."]]];
entries.propercurvefinite=["Proper curve maps are finite", "An actual proper dominant morphism of one-dimensional Noetherian integral curves is finite.", "Nongeneric fibers are proper closed subsets; the generic fiber cannot contain a closed point. Actual finite fibers imply quasi-finiteness and Zariski’s main theorem gives finiteness. Normality and separability are unnecessary.", ["Actual one-dimensional integral X,Y; X is Noetherian.", "An actual proper dominant morphism f:X→Y."], [["Proper curve maps are finite", "Nongeneric fibers are proper closed subsets; the generic fiber cannot contain a closed point. Actual finite fibers imply quasi-finiteness and Zariski’s main theorem gives finiteness. Normality and separability are unnecessary."]]];
entries.propercurveglobal=["Complete normal curves: Cartier pullback degree", "Proper dominant maps of complete normal integral curves satisfy deg(f*D)=[K(X):K(Y)]deg(D), in arbitrary characteristic.", "Actual proper curve geometry derives finiteness and compactness; output supplies genuine pullback equations. No separability, fiber list, order compatibility or degree identity is an input. Ambient normalization and point-image zero remain open.", ["An algebraically closed k of arbitrary characteristic; actual one-dimensional integral locally Noetherian X,Y with normal stalks.", "Proper Y→Spec k and proper dominant f:X→Y; actual CartierAtlas D."], [["Complete normal curves: Cartier pullback degree", "Actual proper curve geometry derives finiteness and compactness; output supplies genuine pullback equations. No separability, fiber list, order compatibility or degree identity is an input. Ambient normalization and point-image zero remain open."]]];

entries.projection[2]='Global Cartier pullback degree is proved for actual proper dominant complete normal curves, including inseparable degree. Actual fibers, local equations and finiteness are derived. Ambient normalization, point-image zero and full real-intersection integration remain open; the ambient projection formula is unfinished.';
entries.projection[3][2]='Open: ambient curve normalization, point-image zero and real-intersection integration. Global Cartier pullback degree on complete normal curves is proved.';
entries.projection[4][entries.projection[4].length-1]=['Complete-curve degree: verified','Actual Cartier pullback degree is proved for proper dominant complete normal curves; continue ambient normalization and point-image zero.'];
for(const id of ['curveprincipal','cartierdegreecomplete']) entries[id][2]+=' The actual proper-curve global Cartier pullback degree is now proved at propercurveglobal; ambient normalization and point-image zero are separate next steps.';

