// Actual curve intersection: formal-24
entries.pointimagezero=["Point image: actual moved restriction has degree zero", "If an actual morphism f:C→X maps every point to one point, construct a moved Cartier restriction B whose actual equations are all 1; therefore deg(B)=0.", "Move by an actual Cartier equation near the image point, then construct the restriction using generic stalk units. Independence of this zero value is proved at actualintersection.", ["Integral actual C,X; C locally Noetherian, compact, with integrally closed stalks.", "An actual f with f(x)=f(ηC) for all x; actual ambient CartierAtlas A."], [["Point image: actual moved restriction has degree zero", "Move by an actual Cartier equation near the image point, then construct the restriction using generic stalk units. Independence of this zero value is proved at actualintersection."]]];
entries.curvemoveindependent=["Actual curves: different moves have equal degree", "Any two genuine moved restrictions B₁,B₂ of the same ambient Cartier divisor to a complete normal integral curve satisfy deg(B₂)=deg(B₁).", "Either ambient move separately may fail to restrict as a rational function. Prove their ratio is a unit at the generic image, restrict it, and apply actual principal degree zero. Neither the ratio nor degree equality is an input.", ["An algebraically closed k of arbitrary characteristic; an integral one-dimensional locally Noetherian C with normal stalks and proper C→Spec k.", "An actual C→X and ambient CartierAtlas; two actual local-equation/stalk restriction data, without numerical identities."], [["Actual curves: different moves have equal degree", "Either ambient move separately may fail to restrict as a rational function. Prove their ratio is a unit at the generic image, restrict it, and apply actual principal degree zero. Neither the ratio nor degree equality is an input."]]];
entries.actualintersection=["Actual Cartier intersection: independent choices and point-image zero", "Define A·C by local orders of a moved Cartier restriction on an actual complete normal curve C→X. Every permitted move and source affine-chart choice gives the same value. A contracted curve has A·C=0.", "Intersection is constructed from actual stalk equations, rather than supplied as a linear interface. Curves originally inside the support are included. Ambient curve normalization and arbitrary real-presentation independence remain open.", ["An algebraically closed k of arbitrary characteristic; a proper one-dimensional integral locally Noetherian C with normal stalks.", "Integral X; any actual f:C→X; actual Cartier local equations and unit transitions A."], [["Actual Cartier intersection: independent choices and point-image zero", "Intersection is constructed from actual stalk equations, rather than supplied as a linear interface. Curves originally inside the support are included. Ambient curve normalization and arbitrary real-presentation independence remain open."]]];
entries.effectiveintersection=["Actual intersection: effective-divisor nonnegativity and positivity", "If an actual effective Cartier divisor A does not contain the curve in its support, A·C≥0. If the curve also meets the support, A·C>0.", "Use the constructed choice-independent actual intersection. Effectivity, full inverse-image support and local orders are derived from actual stalk maps; intersection signs are not inputs.", ["An algebraically closed k of arbitrary characteristic; an actual complete normal integral curve C and morphism f:C→X.", "A.Effective is the local regular-equation definition; f(ηC) avoids support. Strict positivity also requires nonempty inverse-image support."], [["Actual intersection: effective-divisor nonnegativity and positivity", "Use the constructed choice-independent actual intersection. Effectivity, full inverse-image support and local orders are derived from actual stalk maps; intersection signs are not inputs."]]];
entries.curveintersectiondegree=["Actual Cartier intersection: complete-curve degree", "An actual proper dominant morphism f:C→X of complete normal integral curves satisfies A·C=[K(C):K(X)]deg(A), for the constructed choice-independent local-order intersection.", "Identify actual generic stalk restriction equations with the function-field pullback, then use the proved complete-curve degree formula. Inseparable degree is included; the ambient square, normalization and real divisors remain to be integrated.", ["An algebraically closed k of arbitrary characteristic; one-dimensional integral locally Noetherian C,X with normal stalks.", "Proper X→Spec k and proper dominant f:C→X; actual CartierAtlas A."], [["Actual Cartier intersection: complete-curve degree", "Identify actual generic stalk restriction equations with the function-field pullback, then use the proved complete-curve degree formula. Inseparable degree is included; the ambient square, normalization and real divisors remain to be integrated."]]];
entries.projection[2]='Actual choice-independent Cartier curve intersection, contracted-curve zero, effective-divisor signs and proper dominant complete-curve degree are proved, including inseparable degree. Ambient normalization, ambient pullback composition and arbitrary real-presentation independence remain open. The full ambient projection formula is unfinished.';
entries.projection[3][2]='Open: ambient normalization, ambient pullback composition and arbitrary real-presentation independence. Actual Cartier curve zero and degree formulas are proved.';
