entries.intersection[2]='Actual Cartier intersection on complete normal curves is constructed; independence of moves/source charts, contracted-curve zero and effective-divisor nonnegativity/strict positivity are proved. f-nef signs use the contracted-curve definition. Ambient normalization, arbitrary real-presentation linearity and geometric f-ample positivity remain open.';
entries.intersection[3]=['Proved: actual Cartier intersection, move/source-chart independence, point-image zero and effective-divisor nonnegativity/strict positivity.','Open: ambient curve normalization and arbitrary real-presentation linearity/independence.','C is a complete curve contracted by f; f-nef signs are definitional. Geometric f-ample positive degree remains to be integrated.'];
entries.intersection[4]=[['Actual intersection and independence','Construct intersection from actual local equations; permitted moves and source charts give the same value.'],['Effective-divisor signs','Nonnegative without containment, strictly positive on meeting support; signs follow from actual orders.'],['Remaining geometry','Normalization, real-presentation independence and geometric f-ample positivity remain open.']];
for(const id of ['cartiercurve','propercurveglobal','cartierdegreecomplete']) entries[id][2]+=' Subsequent actualintersection constructs the actual Cartier intersection and proves move independence and point-image zero; effectiveintersection proves signs and curveintersectiondegree proves degree scaling. The full ambient real-divisor projection remains open.';

// Actual real Cartier intersection: formal-25
entries.ambientmoving=["Ambient principal moving: intersection invariant", "For any ambient rational function a, (A+div(a))\u00b7C=A\u00b7C, even if a itself cannot restrict to C.", "Cancel the two ambient moves to construct the same genuine restriction. Principal intersection zero is not an input.", ["An algebraically closed k of arbitrary characteristic; a proper integral one-dimensional locally Noetherian C with normal stalks.", "An actual complete normal integral curve C\u2192X, ambient CartierAtlas A and rational a."], [["Ambient principal moving: intersection invariant", "Cancel the two ambient moves to construct the same genuine restriction. Principal intersection zero is not an input."]]];
entries.zerointersection=["Zero Weil coefficients: actual intersection zero", "A Cartier divisor with all actual Weil coefficients zero on a normal ambient Scheme has zero intersection with an actual complete normal curve.", "Normality derives empty full support. Construct the genuine effective restriction and sum local orders. Neither support emptiness nor zero intersection is assumed.", ["An algebraically closed k of arbitrary characteristic; a proper integral one-dimensional locally Noetherian C with normal stalks.", "A normal locally Noetherian integral ambient X; all actual Weil coefficients of A are zero."], [["Zero Weil coefficients: actual intersection zero", "Normality derives empty full support. Construct the genuine effective restriction and sum local orders. Neither support emptiness nor zero intersection is assumed."]]];
entries.integerintersection=["Actual intersection: integer additivity", "Construct actual product equations for D=\u03a3n\u1d62A\u1d62 and prove D\u00b7C=\u03a3n\u1d62(A\u1d62\u00b7C).", "Build actual affine charts and unit transitions, then derive additivity from DVR orders. No linear intersection interface is supplied.", ["An algebraically closed k of arbitrary characteristic; a proper integral one-dimensional locally Noetherian C with normal stalks.", "A finite family of genuine Cartier atlases, arbitrary integer weights and actual C\u2192X."], [["Actual intersection: integer additivity", "Build actual affine charts and unit transitions, then derive additivity from DVR orders. No linear intersection interface is supplied."]]];
entries.realintersectionkernel=["Actual real intersection: cancellation invariant", "Two real coefficient vectors in the same finite family of genuine Cartier generators have equal intersections when their actual Weil coefficients agree.", "Prove actual integer zero relations, clear denominators, then span real zero relations by rational ones. No globally finite ambient support is required.", ["An algebraically closed k of arbitrary characteristic; a proper integral one-dimensional locally Noetherian C with normal stalks.", "A normal locally Noetherian integral ambient Scheme; a finite actual Cartier family and two real vectors."], [["Actual real intersection: cancellation invariant", "Prove actual integer zero relations, clear denominators, then span real zero relations by rational ones. No globally finite ambient support is required."]]];
entries.cartierreindex=["Reindex Cartier covers: intersection invariant", "Repeating a genuine Cartier affine cover with ambient points as indices preserves actual Weil coefficients and complete-normal-curve intersection.", "Compare genuine restrictions. Their discrepancy at each point is an actual source-stalk unit, hence all local orders agree.", ["An algebraically closed k of arbitrary characteristic; a proper integral one-dimensional locally Noetherian C with normal stalks.", "Any genuine Cartier affine cover and an actual complete normal curve C\u2192X."], [["Reindex Cartier covers: intersection invariant", "Compare genuine restrictions. Their discrepancy at each point is an actual source-stalk unit, hence all local orders agree."]]];
entries.realpresentation=["Arbitrary real Cartier presentations: independent", "Generators and affine covers may both differ. Equal actual real Weil coefficients imply equal curve intersections.", "Construct common actual point-indexed charts, merge the finite families and use the proved real zero-relation theorem. Actual nonnormal source normalization and intersection are now proved in normalizedintersection.", ["An algebraically closed k of arbitrary characteristic; a proper integral one-dimensional locally Noetherian C with normal stalks.", "A normal locally Noetherian integral ambient Scheme; two finite genuine Cartier families and arbitrary real vectors."], [["Arbitrary real Cartier presentations: independent", "Construct common actual point-indexed charts, merge the finite families and use the proved real zero-relation theorem. Actual nonnormal source normalization and intersection are now proved in normalizedintersection."]]];
entries.realintersectionpositive=["Effective real divisors: actual intersection signs", "An effective R-Cartier divisor has nonnegative intersection if it does not contain C, and strictly positive intersection if it also meets C. Original Cartier weights may have either sign.", "Construct a nonnegative effective Cartier decomposition; proved arbitrary-presentation independence identifies its degree with the original intersection. Decomposition, support and signs are derived.", ["An algebraically closed k of arbitrary characteristic; a proper integral one-dimensional locally Noetherian C with normal stalks.", "A compact normal locally Noetherian integral ambient Scheme; nonnegative actual real Weil coefficients; C avoids containment in support."], [["Effective real divisors: actual intersection signs", "Construct a nonnegative effective Cartier decomposition; proved arbitrary-presentation independence identifies its degree with the original intersection. Decomposition, support and signs are derived."]]];
entries.actualpullbackintersection=["Actual Cartier pullback: intersection composition", "For actual dominant p:Y\u2192X and g:C\u2192Y, construct P=p* A and prove P\u00b7C=A\u00b7(g\u226bp).", "Use actual stalk composition and ambient function-field maps. Curves originally inside support are included. Actual normalization of any complete integral curve is now proved in curvenormalization.", ["An algebraically closed k of arbitrary characteristic; a proper integral one-dimensional locally Noetherian C with normal stalks.", "Actual dominant p, a genuine complete normal curve g, and ambient CartierAtlas A."], [["Actual Cartier pullback: intersection composition", "Use actual stalk composition and ambient function-field maps. Curves originally inside support are included. Actual normalization of any complete integral curve is now proved in curvenormalization."]]];
entries.realpullbackintersection=["Actual real Cartier pullback: intersection compatibility", "Ambient Cartier pullback commutes with actual curve intersection for arbitrary real weights. Real intersection is zero when the actual curve image is one point.", "Construct every genuine pullback and use proved Cartier composition and point-image zero. No nonnegative-weight or separability restriction.", ["An algebraically closed k of arbitrary characteristic; a proper integral one-dimensional locally Noetherian C with normal stalks.", "Actual dominant p:Y\u2192X and g:C\u2192Y; finite genuine Cartier generators and arbitrary real weights."], [["Actual real Cartier pullback: intersection compatibility", "Construct every genuine pullback and use proved Cartier composition and point-image zero. No nonnegative-weight or separability restriction."]]];
entries.projection[2]="Actual Cartier/R-Cartier intersection, ambient principal moving, integer additivity, arbitrary real-presentation independence, point-image zero, effective-real-divisor signs and ambient pullback composition are proved. Complete-normal-curve degree includes inseparable maps. Normalization of nonnormal ambient curves and full identification with actual image curves/cycle pushforward remain open. The full ambient projection formula is unfinished.";
entries.projection[3][2]='Open: normalization of nonnormal ambient curves and actual image-curve/cycle identification. Actual real intersection independence and ambient pullback composition are proved.';
entries.intersection[2]="Actual Cartier/R-Cartier intersection on complete normal curves is constructed. Arbitrary generators/cover independence, integer additivity, point-image zero and effective-real-divisor signs are proved. f-nef signs use the contracted-complete-curve definition. Normalization of nonnormal curves and geometric f-ample positive degree remain open.";
entries.intersection[3]=['Proved: actual real intersection, arbitrary generators/cover independence, integer additivity, point-image zero and effective-real-divisor intersection signs.','Open: normalization of nonnormal curves and geometric f-ample positive degree.','Relative f-nef signs use the definition on complete curves contracted by f.'];
entries.intersection[4]=[['Actual real intersection and independence','Two arbitrary actual Cartier families/covers representing the same real Weil coefficients have equal intersection.'],['Effective real-divisor signs','Original weights may have either sign; construct an effective decomposition and use proved independence.'],['Remaining geometry','Normalization of nonnormal curves and geometric f-ample positive degree remain open.']];
entries.actualintersection[2]='Intersection is constructed from actual stalk equations and includes curves originally inside support. Subsequent realpresentation proves arbitrary real-presentation independence; realpullbackintersection proves actual ambient pullback compatibility. Normalization of nonnormal curves remains open.';
if(entries.projection.precise) entries.projection.precise.gap="Actual Cartier/R-Cartier intersection, ambient principal moving, integer additivity, arbitrary real-presentation independence, point-image zero, effective-real-divisor signs and ambient pullback composition are proved. Complete-normal-curve degree includes inseparable maps. Normalization of nonnormal ambient curves and full identification with actual image curves/cycle pushforward remain open. The full ambient projection formula is unfinished.";

// Actual normalization and nonnormal curve intersection: formal-26
entries.finitefrobenius=["Finite-type perfect algebras: finite Frobenius", "Every iterated Frobenius of a finite-type commutative algebra over a perfect field is a finite ring homomorphism.", "Finite type, a perfect ground field and exponential characteristic; no separability assumption.", ["Finite type, a perfect ground field and exponential characteristic; no separability assumption."], [["Finite-type perfect algebras: finite Frobenius", "Finite type, a perfect ground field and exponential characteristic; no separability assumption."]]];
entries.pureclosure=["Purely inseparable extensions: finite integral closure", "For finite purely inseparable E\u2282L, finiteness of the integral closure of A in E implies finiteness of its integral closure in L.", "A is a finite-type domain over a perfect field; use actual Frobenius and a linear embedding with twisted scalars.", ["A is a finite-type domain over a perfect field; use actual Frobenius and a linear embedding with twisted scalars."], [["Purely inseparable extensions: finite integral closure", "A is a finite-type domain over a perfect field; use actual Frobenius and a linear embedding with twisted scalars."]]];
entries.perfectclosure=["Normal finite-type domains: closure in any finite extension", "The integral closure of a normal finite-type domain A over a perfect field in any finite fraction-field extension L is a finite A-module.", "Separate the separable and purely inseparable parts; use trace pairing and Frobenius respectively, in arbitrary characteristic.", ["Separate the separable and purely inseparable parts; use trace pairing and Frobenius respectively, in arbitrary characteristic."], [["Normal finite-type domains: closure in any finite extension", "Separate the separable and purely inseparable parts; use trace pairing and Frobenius respectively, in arbitrary characteristic."]]];
entries.finiteclosure=["All finite-type domains: finite integral closure", "A need not be normal: its integral closure in any finite fraction-field extension remains a finite A-module.", "A is a finite-type domain over a perfect field. Actual Noether normalization supplies a polynomial subring, followed by transitivity of integral closure. No separability input.", ["A is a finite-type domain over a perfect field. Actual Noether normalization supplies a polynomial subring, followed by transitivity of integral closure. No separability input."], [["All finite-type domains: finite integral closure", "A is a finite-type domain over a perfect field. Actual Noether normalization supplies a polynomial subring, followed by transitivity of integral closure. No separability input."]]];
entries.relativeclosure=["Actual relative integral closure: finiteness", "If an actual A-algebra S embeds into a finite fraction-field extension L, integralClosure A S is a finite A-module.", "Construct an actual linear embedding of integral closures and use Noetherianity; S is not assumed finite.", ["Construct an actual linear embedding of integral closures and use Noetherianity; S is not assumed finite."], [["Actual relative integral closure: finiteness", "Construct an actual linear embedding of integral closures and use Noetherianity; S is not assumed finite."]]];
entries.normalizationfinite=["Actual variety normalization: finite morphism", "The actual normalization \u03bd:Y\u0303\u2192Y of an integral scheme locally of finite type over a perfect field is finite.", "Use the mathlib Scheme normalization of the actual generic stalk map. Identify integral closures on every actual affine open and prove finite_app, in every dimension and characteristic.", ["Use the mathlib Scheme normalization of the actual generic stalk map. Identify integral closures on every actual affine open and prove finite_app, in every dimension and characteristic."], [["Actual variety normalization: finite morphism", "Use the mathlib Scheme normalization of the actual generic stalk map. Identify integral closures on every actual affine open and prove finite_app, in every dimension and characteristic."]]];
entries.normalizationnormal=["Actual normalization: every stalk is normal", "Every actual local ring of the generic-point normalization of an integral scheme is integrally closed.", "Prove normality of actual affine coordinate rings, then localize to every stalk. Normality is a conclusion, not an input; finite type is not needed here.", ["Prove normality of actual affine coordinate rings, then localize to every stalk. Normality is a conclusion, not an input; finite type is not needed here."], [["Actual normalization: every stalk is normal", "Prove normality of actual affine coordinate rings, then localize to every stalk. Normality is a conclusion, not an input; finite type is not needed here."]]];
entries.normalizationbirational=["Actual variety normalization: birational", "\u03bd:Y\u0303\u2192Y is an actual Scheme isomorphism over a nonempty open of Y.", "Y is integral and locally of finite type over a perfect field. Spread out the actual generic section, then use separatedness to prove the inverse.", ["Y is integral and locally of finite type over a perfect field. Spread out the actual generic section, then use separatedness to prove the inverse."], [["Actual variety normalization: birational", "Y is integral and locally of finite type over a perfect field. Spread out the actual generic section, then use separatedness to prove the inverse."]]];
entries.curvenormalization=["Complete integral curves: normalization properties derived", "Normalization of a complete integral curve is finite, birational, surjective, normal, one-dimensional, locally Noetherian and proper over the ground field.", "k is algebraically closed of arbitrary characteristic. The original curve is only assumed complete, integral and one-dimensional, with no smoothness or normality input. All listed properties are proved.", ["k is algebraically closed of arbitrary characteristic. The original curve is only assumed complete, integral and one-dimensional, with no smoothness or normality input. All listed properties are proved."], [["Complete integral curves: normalization properties derived", "k is algebraically closed of arbitrary characteristic. The original curve is only assumed complete, integral and one-dimensional, with no smoothness or normality input. All listed properties are proved."]]];
entries.normalizedintersection=["Nonnormal curves: actual real intersection and independence", "Define D\u00b7C by local orders on the actual normalization. It is independent of arbitrary real Cartier generators/covers and vanishes for a point image.", "C is any complete integral curve over an algebraically closed field of arbitrary characteristic. Presentation independence requires a normal locally Noetherian ambient Scheme.", ["C is any complete integral curve over an algebraically closed field of arbitrary characteristic. Presentation independence requires a normal locally Noetherian ambient Scheme."], [["Nonnormal curves: actual real intersection and independence", "C is any complete integral curve over an algebraically closed field of arbitrary characteristic. Presentation independence requires a normal locally Noetherian ambient Scheme."]]];
entries.normalizedsigns=["Nonnormal curves: effective real-divisor intersection signs", "For effective R-Cartier D not containing C, D\u00b7C\u22650; if D also meets C, then D\u00b7C>0.", "The actual ambient Scheme is normal, locally Noetherian and compact. C is complete and integral and may be nonnormal. Actual surjectivity of normalization transports support intersections.", ["The actual ambient Scheme is normal, locally Noetherian and compact. C is complete and integral and may be nonnormal. Actual surjectivity of normalization transports support intersections."], [["Nonnormal curves: effective real-divisor intersection signs", "The actual ambient Scheme is normal, locally Noetherian and compact. C is complete and integral and may be nonnormal. Actual surjectivity of normalization transports support intersections."]]];
entries.normalizedpullback=["Nonnormal curves: actual real pullback compatibility", "Construct actual P=p*D and prove P\u00b7C=D\u00b7(g\u226bp), for arbitrary real weights, including curves originally inside support.", "p:Y\u2192X is actually dominant, g:C\u2192Y is any actual map and C is a complete integral curve. This proves pullback composition, not the full cycle projection formula.", ["p:Y\u2192X is actually dominant, g:C\u2192Y is any actual map and C is a complete integral curve. This proves pullback composition, not the full cycle projection formula."], [["Nonnormal curves: actual real pullback compatibility", "p:Y\u2192X is actually dominant, g:C\u2192Y is any actual map and C is a complete integral curve. This proves pullback composition, not the full cycle projection formula."]]];
entries.fieldfunctoriality=["Actual function-field maps: composition", "Actual function-field maps of dominant g:C\u2192Y and f:Y\u2192X satisfy (f\u2218g)*=g*\u2218f*.", "Three actual integral schemes; prove the identity using affine-section germs and actual stalk squares.", ["Three actual integral schemes; prove the identity using affine-section germs and actual stalk squares."], [["Actual function-field maps: composition", "Three actual integral schemes; prove the identity using affine-section germs and actual stalk squares."]]];
entries.normalizeddegree=["Nonnormal source curves: Cartier degree formula", "(f*D)\u00b7C=[k(C):k(X)] deg_X(D), with a possibly nonnormal source C and a complete normal target X.", "f is a proper dominant curve map over an algebraically closed field of arbitrary characteristic. Actual generic-stalk isomorphisms identify the original function fields. The full degree includes the inseparable part. Actual nonnormal-target lifting and degree invariance are now proved; restriction compatibility along the lift remains to be connected.", ["f is a proper dominant curve map over an algebraically closed field of arbitrary characteristic. Actual generic-stalk isomorphisms identify the original function fields. The full degree includes the inseparable part. Actual nonnormal-target lifting and degree invariance are now proved; restriction compatibility along the lift remains to be connected."], [["Nonnormal source curves: Cartier degree formula", "f is a proper dominant curve map over an algebraically closed field of arbitrary characteristic. Actual generic-stalk isomorphisms identify the original function fields. The full degree includes the inseparable part. Actual nonnormal-target lifting and degree invariance are now proved; restriction compatibility along the lift remains to be connected."]]];
entries.normalizedrealdegree=["Nonnormal source curves: real Cartier degree formula", "Every real Cartier combination satisfies the same full function-field degree formula; the real weights need not be nonnegative.", "Actual complete integral source and complete normal target curves; a proper dominant map in arbitrary characteristic. Apply the proved actual integer degree formula termwise.", ["Actual complete integral source and complete normal target curves; a proper dominant map in arbitrary characteristic. Apply the proved actual integer degree formula termwise."], [["Nonnormal source curves: real Cartier degree formula", "Actual complete integral source and complete normal target curves; a proper dominant map in arbitrary characteristic. Apply the proved actual integer degree formula termwise."]]];
entries.normalnormalization=["Normal varieties: normalization is an isomorphism", "If Y is already normal, its actual normalization \u03bd:Y\u0303\u2192Y is a Scheme isomorphism.", "Y is integral and locally of finite type over a perfect field, with every actual stalk normal. Finiteness and birationality are derived from the proved normalization construction.", ["Y is integral and locally of finite type over a perfect field, with every actual stalk normal. Finiteness and birationality are derived from the proved normalization construction."], [["Normal varieties: normalization is an isomorphism", "Y is integral and locally of finite type over a perfect field, with every actual stalk normal. Finiteness and birationality are derived from the proved normalization construction."]]];
entries.projection[2]="Actual normalization, Cartier/R-Cartier intersection, presentation independence, effective-divisor signs, point-image zero and ambient pullback composition are proved for every complete integral source curve, including nonnormal curves. The degree formula to a complete normal target uses the original full function-field degree. Lifting to the normalization of a nonnormal image curve and full actual image-curve/cycle identification remain open; the full ambient projection formula is unfinished.";
entries.projection[3][2]='Open: lifting to a nonnormal image normalization and cycle-pushforward identification. Actual curve normalization, nonnormal-source degree and real intersection are proved.';
entries.intersection[2]="Actual Cartier/R-Cartier intersection is constructed on any complete integral curve using its actual normalization. Presentation independence, integer additivity, point-image zero and effective-divisor nonnegative/strictly positive signs are proved. Relative f-nef signs use the contracted-complete-curve definition. The remaining gap is geometric f-ample positive degree, not intersection definition or curve normalization.";
entries.intersection[3]=['Proved: actual normalization of every complete integral curve, actual real intersection and presentation independence, point-image zero and effective-divisor intersection signs.','Open: deriving strictly positive degree on contracted complete curves from geometric f-ampleness.','Relative f-nef conditions concern only complete curves contracted by f.'];
entries.intersection[4]=[['Normalization of any complete integral curve','Actual normalization is finite, birational, normal and surjective, and remains complete and one-dimensional.'],['Actual real intersection and signs','Sum local orders on the actual normalization. Presentation independence and effective-divisor signs are proved.'],['Remaining geometric ample positivity','Positive degree on contracted curves must still be derived from geometric f-ampleness.']];
entries.actualintersection[2]='The original normal-curve intersection is choice-independent. Subsequent normalizedintersection constructs actual normalization for every complete integral curve and proves arbitrary real-presentation independence. normalizedpullback proves ambient pullback composition.';
if(entries.projection.precise) entries.projection.precise.gap="Actual normalization, Cartier/R-Cartier intersection, presentation independence, effective-divisor signs, point-image zero and ambient pullback composition are proved for every complete integral source curve, including nonnormal curves. The degree formula to a complete normal target uses the original full function-field degree. Lifting to the normalization of a nonnormal image curve and full actual image-curve/cycle identification remain open; the full ambient projection formula is unfinished.";

// Actual normalization lifting: formal-27
entries.finitefunctionfield=["Actual finite dominant maps: finite function-field extension", "An actual finite dominant map f:C\u2192X induces a finite function-field extension k(X)\u2282k(C).", "C and X are arbitrary integral schemes. Normality, separability and dimension one are not required. Derive the result from actual affine rings and localization.", ["C and X are arbitrary integral schemes. Normality, separability and dimension one are not required. Derive the result from actual affine rings and localization."], [["Actual finite dominant maps: finite function-field extension", "C and X are arbitrary integral schemes. Normality, separability and dimension one are not required. Derive the result from actual affine rings and localization."]]];
entries.relativefieldnormalization=["Normalize in the actual source function field: finite", "Normalizing the target of an actual finite dominant map in k(C) gives an actual finite relative normalization.", "The target is integral and locally of finite type over a perfect field. Nonnormal targets and inseparable function-field extensions are included.", ["The target is integral and locally of finite type over a perfect field. Nonnormal targets and inseparable function-field extensions are included."], [["Normalize in the actual source function field: finite", "The target is integral and locally of finite type over a perfect field. Nonnormal targets and inseparable function-field extensions are included."]]];
entries.relativenormalidentity=["Normal finite source: identify actual relative normalization", "A normal source C of a finite dominant map is the actual relative normalization of the target in k(C). The comparison is a Scheme isomorphism.", "Spread out an actual generic section, derive finite birational comparison, and use source normality to obtain the isomorphism. The comparison isomorphism is not an input.", ["Spread out an actual generic section, derive finite birational comparison, and use source normality to obtain the isomorphism. The comparison isomorphism is not an input."], [["Normal finite source: identify actual relative normalization", "Spread out an actual generic section, derive finite birational comparison, and use source normality to obtain the isomorphism. The comparison isomorphism is not an input."]]];
entries.normalizationlift=["Normal source to nonnormal target: actual normalization lift", "Construct l:C\u2192X\u0303 with l\u226b\u03bd_X=f, and prove l finite and dominant.", "f is actually finite and dominant, C is normal, and X is integral and locally of finite type over a perfect field, possibly nonnormal. Use the actual function-field Spec square and normalization universal property.", ["f is actually finite and dominant, C is normal, and X is integral and locally of finite type over a perfect field, possibly nonnormal. Use the actual function-field Spec square and normalization universal property."], [["Normal source to nonnormal target: actual normalization lift", "f is actually finite and dominant, C is normal, and X is integral and locally of finite type over a perfect field, possibly nonnormal. Use the actual function-field Spec square and normalization universal property."]]];
entries.curvenormalizationlift=["Any integral curves: normalization square and degree invariant", "A proper dominant f:C\u2192X lifts to finite dominant f\u0303:C\u0303\u2192X\u0303, with \u03bd_C\u226bf=f\u0303\u226b\u03bd_X and [k(C\u0303):k(X\u0303)]=[k(C):k(X)].", "C and X are complete integral curves over an algebraically closed field of arbitrary characteristic; neither needs to be normal or smooth. Both the actual commuting square and equality of full function-field degrees are proved, including inseparable parts.", ["C and X are complete integral curves over an algebraically closed field of arbitrary characteristic; neither needs to be normal or smooth. Both the actual commuting square and equality of full function-field degrees are proved, including inseparable parts."], [["Any integral curves: normalization square and degree invariant", "C and X are complete integral curves over an algebraically closed field of arbitrary characteristic; neither needs to be normal or smooth. Both the actual commuting square and equality of full function-field degrees are proved, including inseparable parts."]]];
entries.projection[2]="Actual finite normalization, real intersection, presentation independence, signs, point-image zero and ambient pullback composition are proved for arbitrary complete integral curves. Every proper dominant curve map now has an actual normalization lift, commuting square and unchanged original full function-field degree. Remaining: local curve-restriction compatibility along this lift and full actual image-curve/cycle identification. The full ambient projection formula is unfinished.";
entries.projection[3][2]='Open: local curve-restriction compatibility along the normalization lift and full actual image-curve/cycle identification. Actual normalization lifts and full degree invariance are proved.';
if(entries.projection.precise) entries.projection.precise.gap="Actual finite normalization, real intersection, presentation independence, signs, point-image zero and ambient pullback composition are proved for arbitrary complete integral curves. Every proper dominant curve map now has an actual normalization lift, commuting square and unchanged original full function-field degree. Remaining: local curve-restriction compatibility along this lift and full actual image-curve/cycle identification. The full ambient projection formula is unfinished.";

// Actual ambient projection formula: formal-28
entries.curverestrictioncomposition=["Actual curve restriction: compatibility with composition", "Actual Cartier restriction is compatible with a proper dominant curve map; intersection scales by full function-field degree.", "Proved from actual generic-stalk units, equations and DVR orders. The ambient curve map need not be dominant, and the curve may lie in the original support.", ["Proved from actual generic-stalk units, equations and DVR orders. The ambient curve map need not be dominant, and the curve may lie in the original support."], [["Actual curve restriction: compatibility with composition", "Proved from actual generic-stalk units, equations and DVR orders. The ambient curve map need not be dominant, and the curve may lie in the original support."]]];
entries.integralcurveprojection=["Nonnormal integral curves: Cartier projection formula", "Both complete integral curves may be nonnormal: I_C(f\u226bj,A)=[k(C):k(Y)] I_Y(j,A).", "Use actual normalization lifts and restriction compatibility over an algebraically closed field of arbitrary characteristic. Full inseparable degree is retained; no intersection identity is an input.", ["Use actual normalization lifts and restriction compatibility over an algebraically closed field of arbitrary characteristic. Full inseparable degree is retained; no intersection identity is an input."], [["Nonnormal integral curves: Cartier projection formula", "Use actual normalization lifts and restriction compatibility over an algebraically closed field of arbitrary characteristic. Full inseparable degree is retained; no intersection identity is an input."]]];
entries.realintegralcurveprojection=["Nonnormal integral curves: real Cartier projection formula", "Any finite real linear combination of actual Cartier divisors satisfies the curve degree formula.", "Real weights may be positive, negative or zero. Original curves need not be normal or smooth; maps need not be separable.", ["Real weights may be positive, negative or zero. Original curves need not be normal or smooth; maps need not be separable."], [["Nonnormal integral curves: real Cartier projection formula", "Real weights may be positive, negative or zero. Original curves need not be normal or smooth; maps need not be separable."]]];
entries.curvecycleprojection=["Actual curve cycle: pushforward/intersection compatibility", "With actual Order.height dimension weights, the actual generic-point cycle pushes with multiplicity equal to full function-field degree.", "The actual generic residue fields are identified with function fields, and intersection compatibility is proved. There is no hcompat input.", ["The actual generic residue fields are identified with function fields, and intersection compatibility is proved. There is no hcompat input."], [["Actual curve cycle: pushforward/intersection compatibility", "The actual generic residue fields are identified with function fields, and intersection compatibility is proved. There is no hcompat input."]]];
entries.curveimagegeometry=["Actual image scheme: integral, complete, dimension at most one", "Construct the actual scheme-theoretic image of a complete integral curve C\u2192X and prove integrality, properness and the dimension bound.", "X is separated and locally of finite type. Reduced affine image rings, surjectivity and closed-point properties are derived from the map; an image curve is not supplied.", ["X is separated and locally of finite type. Reduced affine image rings, surjectivity and closed-point properties are derived from the map; an image curve is not supplied."], [["Actual image scheme: integral, complete, dimension at most one", "X is separated and locally of finite type. Reduced affine image rings, surjectivity and closed-point properties are derived from the map; an image curve is not supplied."]]];
entries.curveimagecases=["Actual image: point/curve alternatives and point-image zero", "The actual image is either a single point with zero intersection, or a complete integral curve of dimension one.", "The alternatives follow from the actual dimension bound. Closed immersions preserve the actual dimension weight of point closures.", ["The alternatives follow from the actual dimension bound. Closed immersions preserve the actual dimension weight of point closures."], [["Actual image: point/curve alternatives and point-image zero", "The alternatives follow from the actual dimension bound. Closed immersions preserve the actual dimension weight of point closures."]]];
entries.imagecyclemultiplicity=["Ambient cycle multiplicity: full degree to the actual image", "The actual ambient-cycle generic multiplicity equals [k(C):k(image C)].", "Actual closed immersions identify residue fields, so pushforward multiplicity agrees with the actual image function-field degree. This is proved, rather than assumed.", ["Actual closed immersions identify residue fields, so pushforward multiplicity agrees with the actual image function-field degree. This is proved, rather than assumed."], [["Ambient cycle multiplicity: full degree to the actual image", "Actual closed immersions identify residue fields, so pushforward multiplicity agrees with the actual image function-field degree. This is proved, rather than assumed."]]];
entries.ambientprojection=["Actual ambient projection formula: arbitrary real coefficients", "Combine actual images, dimension drops, full degree and intersection to prove ambient compatibility with the actual pushed curve cycle.", "Intersection uses local orders on the actual normalization. Point images give zero, and nonnormal image curves are included.", ["Intersection uses local orders on the actual normalization. Point images give zero, and nonnormal image curves are included."], [["Actual ambient projection formula: arbitrary real coefficients", "Intersection uses local orders on the actual normalization. Point images give zero, and nonnormal image curves are included."]]];
entries.actualprojectionformula=["Actual pullback and ambient cycle: projection formula", "Construct actual Cartier pullbacks P=p*D and prove P\u00b7C=D\u00b7(p\u2218g)_*[C].", "For an actual map g of any complete integral curve, support moving, normalization, real linear extension and actual cycle multiplicities are connected.", ["For an actual map g of any complete integral curve, support moving, normalization, real linear extension and actual cycle multiplicities are connected."], [["Actual pullback and ambient cycle: projection formula", "For an actual map g of any complete integral curve, support moving, normalization, real linear extension and actual cycle multiplicities are connected."]]];
entries.projection[2]="The actual ambient projection formula (p*D)\u00b7C=D\u00b7p_*[C] is proved for actual embedded complete integral curves and arbitrary real Cartier combinations. Intersection uses local orders on the actual normalization; pushforward is the actual mathlib ambient cycle. Image curves may be nonnormal and degree includes inseparable parts; point images give zero intersection and zero pushforward. No intersection compatibility, normalization or image-curve input is assumed. Other geometric steps of the full negativity lemma remain open.";
entries.projection[3]=["k is algebraically closed of arbitrary characteristic; X and Y are integral, and X is separated and locally of finite type over k.", "p:Y\u2192X is actually dominant and quasi-compact; g:C\u21aaY is an actual closed immersion; C is a complete integral curve and may be nonnormal.", "D is an arbitrary real combination of finitely many actual Cartier divisors. The theorem constructs the actual pullback equations."];
entries.projection[4]=[["Construct actual pullback", "Construct actual p*D charts and local equations; prove compatibility with intersection composition."], ["Actual image and alternatives", "Prove the actual image integral, complete and at most one-dimensional, then derive the point/curve alternatives."], ["Actual multiplicity and local orders", "Identify the ambient-cycle multiplicity with the full degree to the actual image and combine the local-order formula."], ["Projection for the embedded curve", "The actual ambient projection formula (p*D)\u00b7C=D\u00b7p_*[C] is proved for actual embedded complete integral curves and arbitrary real Cartier combinations. Intersection uses local orders on the actual normalization; pushforward is the actual mathlib ambient cycle. Image curves may be nonnormal and degree includes inseparable parts; point images give zero intersection and zero pushforward. No intersection compatibility, normalization or image-curve input is assumed. Other geometric steps of the full negativity lemma remain open."]];
if(entries.projection.precise) entries.projection.precise.gap="The actual ambient projection formula (p*D)\u00b7C=D\u00b7p_*[C] is proved for actual embedded complete integral curves and arbitrary real Cartier combinations. Intersection uses local orders on the actual normalization; pushforward is the actual mathlib ambient cycle. Image curves may be nonnormal and degree includes inseparable parts; point images give zero intersection and zero pushforward. No intersection compatibility, normalization or image-curve input is assumed. Other geometric steps of the full negativity lemma remain open.";

entries.projection[1]='(π*D)·Γ = D·π_*[Γ] is proved for actual divisors, curves and ambient cycles, including point images and nonnormal curve images.';

// Actual nef pullback and cycle cases, formal-29
entries.fixedpullbackintersection=["Fixed actual pullback: intersection compatibility for all curves", "Any one actual Cartier atlas with the actual pullback equations satisfies intersection composition for every complete normal integral curve.", "Proved from actual local equations and stalk maps; no separate pullback is chosen for each curve.", ["Proved from actual local equations and stalk maps; no separate pullback is chosen for each curve."], [["Fixed actual pullback: intersection compatibility for all curves", "Proved from actual local equations and stalk maps; no separate pullback is chosen for each curve."]]];
entries.canonicalrealpullback=["One actual real pullback: every complete integral curve", "Fix one actual P=p*D; its intersection on every complete integral curve agrees with ambient composition.", "Nonnormal curves, curves in the original support and arbitrary real weights are included. Actual charts and rational equations are constructed independently of the test curve.", ["Nonnormal curves, curves in the original support and arbitrary real weights are included. Actual charts and rational equations are constructed independently of the test curve."], [["One actual real pullback: every complete integral curve", "Nonnormal curves, curves in the original support and arbitrary real weights are included. Actual charts and rational equations are constructed independently of the test curve."]]];
entries.nefpull=["Actual relative nefness preserved by pullback", "If D is f-nef, the same actual pullback p*D is (p\u226bf)-nef.", "Relative nefness is defined on actual contracted complete integral curves using local orders on the actual normalization. One fixed actual pullback P preserves relative nefness for all test curves. Image completeness, contraction and degree scaling are derived; no intersection compatibility or nef-transport input is assumed.", ["k is algebraically closed of arbitrary characteristic. X and Y are integral; X is separated and locally of finite type.", "Actual dominant p:Y\u2192X and f:X\u2192S; finite actual Cartier family with arbitrary real weights.", "Relative nefness is the actual contracted-curve definition, not a transport input."], [["Relative definition", "Test actual intersection only on actual contracted complete integral curves."], ["One fixed pullback preserves nefness", "Relative nefness is defined on actual contracted complete integral curves using local orders on the actual normalization. One fixed actual pullback P preserves relative nefness for all test curves. Image completeness, contraction and degree scaling are derived; no intersection compatibility or nef-transport input is assumed."]]];
entries.projectioncases=["Actual cycle projection: both cases", "Actual point images push to zero; curve images push with full degree, and actual real intersection satisfies the corresponding identities.", "The actual image is a point with zero actual intersection and zero ambient one-cycle pushforward, or a complete integral curve with pushforward multiplicity equal to the full function-field degree to that image. Nonnormal images and inseparable degree are included; no hcompat or image-testability input is assumed.", ["A complete integral curve C\u2192X; X is an integral separated locally finite-type ambient scheme.", "Algebraically closed k of arbitrary characteristic; actual Cartier family, arbitrary real weights and actual Order.height dimensions."], [["Point-image cycle zero", "The actual point image and dimension drop give zero actual one-cycle pushforward."], ["Both actual cases", "The actual image is a point with zero actual intersection and zero ambient one-cycle pushforward, or a complete integral curve with pushforward multiplicity equal to the full function-field degree to that image. Nonnormal images and inseparable degree are included; no hcompat or image-testability input is assumed."]]];
entries.chow[2]='Actual finite normalization, full ambient curve projection, relative nef pullback, real Cartier push-pull and effective support pullback are proved. Hartshorne finite-cover relative projectivity is still open. Fiber dichotomy additionally needs the separate high-dimensional curve selection and connectedness proof.';
entries.chow[3]=['Proved: actual graph closure is proper, birational and surjective.','Open: relative projectivity in the Hartshorne finite affine-cover construction.','Proved: actual finite normalization, real Cartier support/push-pull, actual projection formula and relative nef preservation.'];
entries.chow[4][2]=['Normalization and geometric formulas: verified','Actual finite normalization, ambient projection, relative nef pullback and real Cartier geometric push-pull are proved. Full Chow projectivity remains open.'];

// Actual curve construction, formal-30
entries.affinelinepoint=["An affine line through the prescribed point", "In the polynomial ring, construct a prime properly below the point maximal ideal, with quotient actually isomorphic to k[T].", "Send one coordinate to T and the others to their point values. The surjective restriction map has the required line as its kernel.", ["Send one coordinate to T and the others to their point values. The surjective restriction map has the required line as its kernel."], [["An affine line through the prescribed point", "Send one coordinate to T and the others to their point values. The surjective restriction map has the required line as its kernel."]]];
entries.affinecurvepoint=["An affine integral curve through the prescribed closed point", "In a positive-dimensional finite-type integral affine variety, construct a prime P properly below the prescribed maximal ideal; the actual quotient has dimension one.", "Over an algebraically closed field of arbitrary characteristic, Noether normalization, the constructed line and going-down produce P. Integrality proves the dimension bound and nonfield property; curve existence is not an input.", ["Over an algebraically closed field of arbitrary characteristic, Noether normalization, the constructed line and going-down produce P. Integrality proves the dimension bound and nonfield property; curve existence is not an input."], [["An affine integral curve through the prescribed closed point", "Over an algebraically closed field of arbitrary characteristic, Noether normalization, the constructed line and going-down produce P. Integrality proves the dimension bound and nonfield property; curve existence is not an input."]]];
entries.functionfielddimension=["Actual function-field transcendence degree controls dimension", "A finite-type integral scheme with actual function-field transcendence degree at most one has Krull dimension at most one.", "Apply Noether normalization and integral dimension control on actual affine charts, then use actual coheight to recover the global dimension.", ["Apply Noether normalization and integral dimension control on actual affine charts, then use actual coheight to recover the global dimension."], [["Actual function-field transcendence degree controls dimension", "Apply Noether normalization and integral dimension control on actual affine charts, then use actual coheight to recover the global dimension."]]];
entries.completecurveclosure=["The actual complete closure of a curve", "For an integral one-dimensional immersed curve in a proper ambient scheme, its actual scheme-image closure is integral, proper and one-dimensional.", "Reducedness, irreducibility, the function-field embedding and the open immersion are derived for the actual image; being a curve is not assumed.", ["Reducedness, irreducibility, the function-field embedding and the open immersion are derived for the actual image; being a curve is not assumed."], [["The actual complete closure of a curve", "Reducedness, irreducibility, the function-field embedding and the open immersion are derived for the actual image; being a curve is not assumed."]]];
entries.completecurvepoint=["Complete integral variety: a curve through the prescribed closed point", "Every nongeneric closed point of a proper integral variety lies on an actually closed-immersed proper integral curve.", "Construct a one-dimensional prime quotient on an actual affine chart and take its actual closure, retaining the prescribed point. The curve, its dimension, properness and closed immersion are all constructed.", ["Construct a one-dimensional prime quotient on an actual affine chart and take its actual closure, retaining the prescribed point. The curve, its dimension, properness and closed immersion are all constructed."], [["Complete integral variety: a curve through the prescribed closed point", "Construct a one-dimensional prime quotient on an actual affine chart and take its actual closure, retaining the prescribed point. The curve, its dimension, properness and closed immersion are all constructed."]]];
entries.integralclosedsubscheme=["The actual integral subscheme of a closed irreducible set", "The vanishing-ideal subscheme of a closed irreducible set is actually reduced and irreducible; its closed immersion has exactly that set as image.", "Prove reducedness of radical quotients on each affine chart and descend along the actual open cover. Reducedness of the subscheme is derived.", ["Prove reducedness of radical quotients on each affine chart and descend along the actual open cover. Reducedness of the subscheme is derived."], [["The actual integral subscheme of a closed irreducible set", "Prove reducedness of radical quotients on each affine chart and descend along the actual open cover. Reducedness of the subscheme is derived."]]];
entries.nonisolatedcurve=["Proper fiber: a curve through a nonisolated closed point", "A nonisolated closed point of a proper scheme lies on an actual proper integral curve, even when the fiber is reducible or nonreduced.", "Finiteness of Noetherian irreducible components gives a positive-dimensional component through the point. Construct its reduced integral subscheme and apply the actual closed-point curve theorem.", ["Finiteness of Noetherian irreducible components gives a positive-dimensional component through the point. Construct its reduced integral subscheme and apply the actual closed-point curve theorem."], [["Proper fiber: a curve through a nonisolated closed point", "Finiteness of Noetherian irreducible components gives a positive-dimensional component through the point. Construct its reduced integral subscheme and apply the actual closed-point curve theorem."]]];
entries.cover=["Actual complete curve through each exceptional closed point", "Every exceptional closed point lies on an actual proper integral curve contracted by f.", "For an actual proper birational morphism to a normal base, Zariski main theorem excludes isolated points in each exceptional fiber. Construct a proper integral curve in the actual fiber and closed-immerse it in the ambient scheme. Arbitrary-characteristic algebraically closed field; no curve-existence input.", ["Algebraically closed k of arbitrary characteristic; integral X and Y, with Y locally of finite type and all stalks integrally closed.", "f is an actual proper birational morphism and x is closed.", "f is not an isomorphism on any open neighborhood of f(x); this is the actual center condition."], [["Actual nonisolated fiber", "Zariski main theorem excludes isolated points in exceptional fibers."], ["Actual complete integral curve constructed", "For an actual proper birational morphism to a normal base, Zariski main theorem excludes isolated points in each exceptional fiber. Construct a proper integral curve in the actual fiber and closed-immerse it in the ambient scheme. Arbitrary-characteristic algebraically closed field; no curve-existence input."]]];
entries.curves=["Zero exceptional prime coefficient: actual contracted curve", "For effective B with zero coefficient at an exceptional prime, construct a proper contracted integral curve C not contained in Supp B and with B\u00b7C\u22650.", "A zero prime coefficient of an effective actual real Cartier divisor places that prime outside the actual Weil-support closure. Construct a closed point outside support and an actual contracted curve through it via exceptional curve coverage. The curve is not contained in support, and its actual normalized intersection is nonnegative. The entire curve need not lie in F. This step does not use connected fibers from part (2).", ["Normal integral X and Y, X compact and locally Noetherian; proper birational f; Y locally finite type over any algebraically closed field.", "B is an actual finite Cartier family with arbitrary real weights and nonnegative actual Weil coefficients.", "The codimension-one point has zero coefficient and its image belongs to the actual center.", "This proves the geometric step after a zero exceptional prime is provided. The full proof must separately derive that condition from effectivity of f_*D."], [["Zero coefficient and support", "Two codimension-one points cannot strictly specialize to each other; finite Weil support therefore excludes the zero-coefficient prime."], ["Actual closed point and contracted curve", "Choose x outside support in the closure of the prime. The center condition specializes; construct an actual proper contracted curve through x."], ["Actual nonnegative intersection", "A zero prime coefficient of an effective actual real Cartier divisor places that prime outside the actual Weil-support closure. Construct a closed point outside support and an actual contracted curve through it via exceptional curve coverage. The curve is not contained in support, and its actual normalized intersection is nonnegative. The entire curve need not lie in F. This step does not use connected fibers from part (2)."]]];
entries.connected[3][3]='Proved: actual complete contracted curves through all exceptional closed points. Selecting a curve that also meets support without being contained in it remains a separate high-dimensional step.';
entries.connected[4][3]=['High-dimensional crossing curve: still open','Actual complete contracted curve coverage is proved. A curve meeting support without being contained in it still requires a proof. This step belongs only to part (2).'];

// Actual center and actual negativity witness, formal-31
entries.actualnegativecenter=["Actual negative coefficients lie over the exceptional center", "If actual cycle pushforward is effective, every negative coefficient has image outside every isomorphism open.", "Over every actual isomorphism open, the unique preimage has equal coheight, isomorphic stalk and residue degree one. Actual cycle pushforward therefore preserves its coefficient. If pushforward is effective, a negative coefficient cannot lie over that open, so its image belongs to the actual center. No numerical strict-transform model or exceptional-identification input.", ["Actual quasi-compact scheme morphism and actual real cycle.", "Actual Order.coheight weights; actual pushforward has nonnegative coefficients."], [["Actual coefficient over an isomorphism open", "Unique preimage, equal actual coheight and residue degree one preserve the coefficient."], ["Negative coefficients identify the actual center", "Over every actual isomorphism open, the unique preimage has equal coheight, isomorphic stalk and residue degree one. Actual cycle pushforward therefore preserves its coefficient. If pushforward is effective, a negative coefficient cannot lie over that open, so its image belongs to the actual center. No numerical strict-transform model or exceptional-identification input."]]];
entries.core=["Actual geometric negativity: E witness still needed", "If actual f_*D is effective and \u2212D is f-nef, an effective actual E covering exceptional primes with strictly negative contracted-curve degree implies actual D is effective.", "The actual geometric contradiction for part (1) is proved: actual Cartier support finiteness gives finite coefficients; effectivity of actual pushforward identifies negative primes with the center; the maximum ratio gives a zero coefficient; constructed actual contracted curves and actual nonnegative intersections finish the contradiction. The same E is still assumed effective, positive at exceptional primes and of strictly negative actual degree on every contracted closed-immersed curve. There is no hcurve, supplied intersection map or center-identification input. Constructing E and deriving geometric ample positivity remain open; this is still conditional.", ["Arbitrary-characteristic algebraically closed field; normal integral X and Y; compact X; proper birational f; Y locally finite type.", "D and E are actual finite Cartier presentations with real weights. Actual f_*D is effective, and \u2212D is f-nef on actual contracted complete curves.", "Remaining E witness: E is actually effective and has positive coefficient at every prime over the actual center.", "Remaining E witness: E\u00b7C<0 on all actual contracted proper closed-immersed integral curves. Deriving this from geometric \u2212E f-ample remains open."], [["Actual finite coefficients and center", "Construct finite actual coefficients and derive that every negative coefficient lies over the actual center."], ["Actual maximum ratio", "Obtain e>0 and effective B=D+eE with zero coefficient at a negative prime."], ["Actual curve and intersection", "The support-outside point, actual contracted curve and B\u00b7C\u22650 are all constructed."], ["Conditional contradiction completed", "Actual \u2212D f-nef gives D\u00b7C\u22640; the E witness gives E\u00b7C<0. Actual intersection linearity yields a contradiction."]]];
entries.curves[3][3]='Proved: effectivity of actual f_*D places each negative coefficient over the actual center. The main proof still needs E coverage and strict negative degree.';

// Actual support-crossing curves, formal-32
entries.affinelineavoid=["An affine line through the point with support avoidance", "At a prescribed zero of a nonzero polynomial, construct an actual line through the point not contained in its zero set.", "Polynomial evaluation over an infinite field selects a direction. An explicit surjective restriction map has actual prime kernel avoiding the polynomial.", ["Polynomial evaluation over an infinite field selects a direction. An explicit surjective restriction map has actual prime kernel avoiding the polynomial."], [["An affine line through the point with support avoidance", "Polynomial evaluation over an infinite field selects a direction. An explicit surjective restriction map has actual prime kernel avoiding the polynomial."]]];
entries.affinecurveavoid=["Affine integral curve: through the point with avoidance", "If a nonzero function v vanishes at the prescribed closed point, construct an actual one-dimensional prime P below m with v not in P.", "Integrality under Noether normalization gives a nonzero base-ring element in (v). Choose a line avoiding it, then apply going-down. Neither curve existence nor avoidance is assumed.", ["Integrality under Noether normalization gives a nonzero base-ring element in (v). Choose a line avoiding it, then apply going-down. Neither curve existence nor avoidance is assumed."], [["Affine integral curve: through the point with avoidance", "Integrality under Noether normalization gives a nonzero base-ring element in (v). Choose a line avoiding it, then apply going-down. Neither curve existence nor avoidance is assumed."]]];
entries.completecurveavoid=["Complete integral variety: a crossing curve at a support point", "A prescribed closed point of a nonempty proper closed subset lies on an actual proper integral curve not contained in that subset.", "The actual affine zero locus supplies a nonzero vanishing function. Construct an avoiding curve and take its actual scheme closure, retaining the point and noncontainment.", ["The actual affine zero locus supplies a nonzero vanishing function. Construct an avoiding curve and take its actual scheme closure, retaining the point and noncontainment."], [["Complete integral variety: a crossing curve at a support point", "The actual affine zero locus supplies a nonzero vanishing function. Construct an avoiding curve and take its actual scheme closure, retaining the point and noncontainment."]]];
entries.connectedcrossing=["Connected proper scheme in any dimension: an actual crossing curve", "Every nonempty proper closed subset of a connected proper scheme is met by an actual proper integral curve not contained in that subset.", "The scheme may be reducible, nonreduced and of any dimension. Finite irreducible components and connectedness give a crossing component. Construct its reduced integral subscheme and the curve. Connectedness is the theorem hypothesis; curve existence is proved.", ["The scheme may be reducible, nonreduced and of any dimension. Finite irreducible components and connectedness give a crossing component. Construct its reduced integral subscheme and the curve. Connectedness is the theorem hypothesis; curve existence is proved."], [["Connected proper scheme in any dimension: an actual crossing curve", "The scheme may be reducible, nonreduced and of any dimension. Finite irreducible components and connectedness give a crossing component. Construct its reduced integral subscheme and the curve. Connectedness is the theorem hypothesis; curve existence is proved."]]];
entries.fiber=["Actual support dichotomy on connected contracted schemes", "For effective actual D with \u2212D f-nef, a connected proper contracted scheme is disjoint from Supp D or entirely in it. Application to all fibers still needs fiber connectedness.", "For an effective actual real Cartier divisor D with \u2212D nef on actual contracted complete curves, every actual connected proper contracted scheme Z\u2192X is proved disjoint from actual Supp D or entirely mapped into it. High-dimensional crossing-curve selection and strict positive actual intersection are derived; Z may be reducible or nonreduced. Applying this to all actual proper birational fibers still needs their independently proved connectedness and the corresponding base-field interfaces. This result does not prove global fiber connectedness.", ["Algebraically closed field of arbitrary characteristic; normal integral compact locally Noetherian X.", "Actual finite Cartier family with real weights is effective; \u2212D is nef on actual contracted complete curves.", "Z\u2192X is proper over the base field and contracted by f. Connectedness of Z is an explicit theorem hypothesis.", "Remaining application: derive connectedness of every actual proper birational fiber from the geometric assumptions and connect the general fiber base fields."], [["Assume partial support meeting", "The actual pulled-back closed set T is nonempty and proper."], ["Actual high-dimensional crossing curve: proved", "Construct a proper integral curve meeting T without being contained in it."], ["Actual positive degree contradicts nefness", "Actual intersection is strictly positive while \u2212D f-nef makes it nonpositive, proving the dichotomy."]]];
entries.connected[0]='Connectedness of actual proper birational fibers';
entries.connected[1]='Remaining: prove connectedness of actual fibers of proper birational morphisms to normal bases. High-dimensional crossing-curve selection is proved.';
entries.connected[2]='The Hartshorne III §11 normality, formal-functions and idempotent argument still needs actual sheaf-theoretic bridges; the final local-ring contradiction is verified. Actual crossing curves are now constructed in every dimension, including reducible and nonreduced complete schemes. This node retains only actual fiber connectedness.';
entries.connected[3][3]='Proved: actual complete integral crossing curves on all connected proper schemes. Remaining: connectedness of actual proper birational fibers.';
entries.connected[4][3]=['High-dimensional crossing curve: proved','Constructed actual complete integral curves meeting a proper closed subset without being contained in it, including reducible and nonreduced connected proper schemes.'];
entries.chow[2]=entries.chow[2].replace('separate high-dimensional curve selection and connectedness proof','separate actual fiber connectedness proof; high-dimensional crossing-curve selection is proved');

entries.effectivetwist=["Affine-base denominators: construct an effective Cartier representative", "Every actual Cartier divisor over an affine birational base has a constructed effective principal twist.", "Compactness selects finitely many actual affine charts. The birational function-field isomorphism moves equations to the base fraction field; a common nonzero denominator gives regular equations in actual stalks. Unit transitions cover every chart. No section-existence or effectivity input.", ["Compactness selects finitely many actual affine charts. The birational function-field isomorphism moves equations to the base fraction field; a common nonzero denominator gives regular equations in actual stalks. Unit transitions cover every chart. No section-existence or effectivity input."], [["Affine-base denominators: construct an effective Cartier representative", "Compactness selects finitely many actual affine charts. The birational function-field isomorphism moves equations to the base fraction field; a common nonzero denominator gives regular equations in actual stalks. Unit transitions cover every chart. No section-existence or effectivity input."]]];

entries.normalizedprincipal=["Every complete integral curve: ambient principal invariance", "Actual normalized intersection is unchanged by every ambient principal twist.", "The original curve may be nonnormal and lie in the principal function support. Construct its actual finite normalization and compare genuine Cartier restrictions.", ["The original curve may be nonnormal and lie in the principal function support. Construct its actual finite normalization and compare genuine Cartier restrictions."], [["Every complete integral curve: ambient principal invariance", "The original curve may be nonnormal and lie in the principal function support. Construct its actual finite normalization and compare genuine Cartier restrictions."]]];

entries.effectiveexceptional=["Effective E and positive exceptional coefficients: constructed", "Given an actual strictly negative Cartier divisor, construct effective E and prove positive coefficients at every exceptional prime.", "Effectivity and exceptional coverage are outputs. A zero exceptional coefficient yields an actual contracted curve with E\u00b7C\u22650; principal invariance and strict negative degree contradict it. Construction of O(1) section-cover data from projectivity remains open.", ["Effectivity and exceptional coverage are outputs. A zero exceptional coefficient yields an actual contracted curve with E\u00b7C\u22650; principal invariance and strict negative degree contradict it. Construction of O(1) section-cover data from projectivity remains open."], [["Effective E and positive exceptional coefficients: constructed", "Effectivity and exceptional coverage are outputs. A zero exceptional coefficient yields an actual contracted curve with E\u00b7C\u22650; principal invariance and strict negative degree contradict it. Construction of O(1) section-cover data from projectivity remains open."]]];

entries.completeaffineavoid=["A complete curve meets the complement of an affine open", "An actual closed complete integral curve cannot lie entirely inside an ambient affine open.", "Otherwise the closed factorization makes the complete curve affine. Its actual global coordinate ring is a field by properness, hence dimension zero, contradicting dimension one.", ["Otherwise the closed factorization makes the complete curve affine. Its actual global coordinate ring is a field by properness, hence dimension zero, contradicting dimension one."], [["A complete curve meets the complement of an affine open", "Otherwise the closed factorization makes the complete curve affine. Its actual global coordinate ring is a field by properness, hence dimension zero, contradicting dimension one."]]];

entries.normalizedcartiersigns=["Actual Cartier effectivity and positive intersection", "An effective Cartier divisor has nonnegative degree on every complete integral curve outside its support, strictly positive when they meet.", "The actual finite normalization transfers generic avoidance and support meeting, including singular and nonnormal complete integral curves.", ["The actual finite normalization transfers generic avoidance and support meeting, including singular and nonnormal complete integral curves."], [["Actual Cartier effectivity and positive intersection", "The actual finite normalization transfers generic avoidance and support meeting, including singular and nonnormal complete integral curves."]]];

entries.affinesectionpositive=["Affine section cover \u21d2 actual positive degree", "Actual effective linearly equivalent divisors with affine nonvanishing loci covering the scheme imply strictly positive actual degree on every closed complete integral curve.", "Inputs are actual section and affine nonvanishing-cover geometry, with no degree condition. Choose a section nonvanishing at the curve generic point; the complete curve must meet its zero divisor. Actual effective positivity and principal invariance give the original positive degree. Construction from a projective embedding is a separate open node.", ["Inputs are actual section and affine nonvanishing-cover geometry, with no degree condition. Choose a section nonvanishing at the curve generic point; the complete curve must meet its zero divisor. Actual effective positivity and principal invariance give the original positive degree. Construction from a projective embedding is a separate open node."], [["Affine section cover \u21d2 actual positive degree", "Inputs are actual section and affine nonvanishing-cover geometry, with no degree condition. Choose a section nonvanishing at the curve generic point; the complete curve must meet its zero divisor. Actual effective positivity and principal invariance give the original positive degree. Construction from a projective embedding is a separate open node."]]];

entries.cartierinverse=["Actual Cartier negation and negative intersection", "Invert actual local equations and stalk units to construct \u2212A and prove (\u2212A)\u00b7C=\u2212(A\u00b7C).", "Actual DVR orders give opposite coefficients; proved real Cartier presentation independence gives opposite intersection on every complete integral curve.", ["Actual DVR orders give opposite coefficients; proved real Cartier presentation independence gives opposite intersection on every complete integral curve."], [["Actual Cartier negation and negative intersection", "Actual DVR orders give opposite coefficients; proved real Cartier presentation independence gives opposite intersection on every complete integral curve."]]];
entries.projectivesections=["Relative O(1): actual Cartier section cover", "Remaining: construct actual O(1) Cartier equations and coordinate sections from the relative projective closed embedding, with affine nonvanishing loci covering X.", "Use homogeneous coordinate ratios on nonempty standard opens to construct actual Cartier equations, stalk unit transitions, effective coordinate sections and their affine nonvanishing-cover. Denominator clearing, E effectivity, exceptional coverage and positive actual degree are separately proved. This node retains only construction from the projective closed embedding.", ["Actual closed embedding i:X\u2192P^n_R over affine Spec R.", "Construct homogeneous-ratio equations and actual stalk unit transitions.", "Construct effective coordinate sections and identify their affine nonvanishing loci and cover."], [["Actual homogeneous-ratio equations", "Choose a coordinate nonvanishing at the generic point, then form ratios on each nonempty standard chart."], ["Coordinate sections and affine loci", "Prove transitions, effectivity and zero loci; standard affine opens and the closed embedding give the cover."]]];
entries.antiample=["E constructed: projective coordinate data remain", "Effective E, principal invariance and positive exceptional coefficients are proved. Remaining: actual O(1) section data.", "Actual denominator clearing over the affine base replaces the direct-image nonzero-section route, removing its quasi-coherence and nonvanishing inputs. E effectivity and exceptional coverage are constructed. Actual affine section-cover geometry also proves positive degree. Construction of these O(1) Cartier data from the relative projective embedding remains, so the application stays conditional.", ["Proved: actual affine-base denominators construct an effective principal twist.", "Proved: normalized intersection invariance and exceptional E coverage.", "Proved: actual affine section-cover geometry implies positive degree, without assuming a degree sign.", "Remaining: construct actual O(1) Cartier section-cover data from the projective closed embedding."], [["Affine-base denominator clearing: proved", "A nonzero common base-ring denominator makes the finite actual Cartier equations effective."], ["Actual positive degree: proved", "Affine section-cover geometry proves positive complete-curve degree, then negate the Cartier divisor."], ["Exceptional E coverage: proved", "A zero coefficient produces an actual contracted curve contradicting strictly negative degree."], ["Remaining projective coordinate construction", "Build the actual section-cover data from homogeneous O(1) equations."]]];
entries.intersection=["Geometric section positivity: proved with explicit data", "Actual relative nefness uses contracted complete curves. Affine nonvanishing-cover geometry proves positive Cartier degree; projective coordinate construction remains.", "Actual Cartier and real intersections, normalization, effective signs and support positivity are proved. The new geometric proof starts with actual effective linearly equivalent divisors whose affine nonvanishing loci cover the scheme and proves positive degree on every closed complete integral curve. There is no supplied positive-degree input. Construction of these data for relative O(1) is retained at projectivesections.", ["Proved: actual complete-curve intersection and relative nef signs.", "Proved: actual affine nonvanishing section cover implies positive degree.", "Remaining: construct the projective coordinate section cover."], [["Relative nef definition", "Test actual contracted complete curves only; \u2212D f-nef gives D\u00b7C\u22640."], ["Affine geometric positivity: proved", "A complete curve meets an effective coordinate zero divisor; principal invariance gives positive original degree."], ["O(1) coordinate data remain", "Connect the actual homogeneous equations and standard coordinate open cover."]]];
entries.core=["Actual negativity: geometric section-cover input only", "Actual f_*D effective and \u2212D f-nef, together with actual Cartier affine nonvanishing-cover geometry, imply effective actual D. E and degree signs are constructed.", "The first-part argument is connected to actual geometric section-cover data: affine nonvanishing loci give positive degree; negate the Cartier divisor, clear denominators to construct effective E and prove positive exceptional coefficients; then use maximum ratios, actual contracted curves and actual intersections. No E effectivity, E coverage, numerical sign, supplied intersection functional or curve-existence input remains. Actual Cartier affine section-cover data are still required; their construction from relative O(1) remains, so the complete main theorem is still open.", ["Algebraically closed field of arbitrary characteristic; normal integral X,Y, affine Y, compact X, proper birational f, finite-type base geometry.", "Actual finite Cartier family with arbitrary real weights D; actual f_*D effective and \u2212D relatively nef.", "Only additional geometric input: actual Cartier effective linearly equivalent sections whose affine nonvanishing loci cover X.", "Remaining: construct these O(1) data from the relative projective closed embedding. The complete theorem is not marked proved."], [["Geometric positive degree", "Actual affine nonvanishing-cover geometry implies positive complete-curve degree."], ["Effective E and coverage", "Clear denominators and use actual contracted curves to prove positive exceptional coefficients."], ["Maximum ratio and actual contradiction", "Actual negative-coefficient centers, zero coefficient, contracted curves and actual intersections give the contradiction."], ["Conditional actual geometric theorem", "Degree signs, E effectivity and coverage are derived. Actual O(1) geometric section-cover construction still remains."]]];

entries.projratios=["Actual Proj ratios and stalk units", "Equal-degree coordinate ratios give actual Proj stalk elements; they are units exactly where the numerator is nonvanishing.", "Use genuine homogeneous localization and the actual Proj stalk isomorphism to prove multiplication identities and coordinate-section germs. No symbolic ratio or unit-criterion input.", ["Use genuine homogeneous localization and the actual Proj stalk isomorphism to prove multiplication identities and coordinate-section germs. No symbolic ratio or unit-criterion input."], [["Actual Proj ratios and stalk units", "Use genuine homogeneous localization and the actual Proj stalk isomorphism to prove multiplication identities and coordinate-section germs. No symbolic ratio or unit-criterion input."]]];

entries.projpullback=["Pull back coordinate ratios: actual rational functions", "Pull coordinate sections to the integral scheme and into its actual function field; prove local compatibility, nonvanishing and ratio multiplication.", "No dominance of the closed embedding is assumed. Nonvanishing generic coordinates give an actual unit germ; injectivity of section-to-function-field maps proves nonzero ratios.", ["No dominance of the closed embedding is assumed. Nonvanishing generic coordinates give an actual unit germ; injectivity of section-to-function-field maps proves nonzero ratios."], [["Pull back coordinate ratios: actual rational functions", "No dominance of the closed embedding is assumed. Nonvanishing generic coordinates give an actual unit germ; injectivity of section-to-function-field maps proves nonzero ratios."]]];

entries.projcartier=["Projective coordinates construct an actual Cartier atlas", "On an actual Proj closed embedding, choose a generic coordinate and construct ratio equations with genuine stalk-unit transitions.", "Closed-embedding preimages of nonempty standard opens form actual affine charts. Proj stalk ratio units and actual pullback multiplication prove transitions; the Cartier atlas is an output.", ["Closed-embedding preimages of nonempty standard opens form actual affine charts. Proj stalk ratio units and actual pullback multiplication prove transitions; the Cartier atlas is an output."], [["Projective coordinates construct an actual Cartier atlas", "Closed-embedding preimages of nonempty standard opens form actual affine charts. Proj stalk ratio units and actual pullback multiplication prove transitions; the Cartier atlas is an output."]]];

entries.projcoordsections=["Coordinate zero loci and affine nonvanishing cover", "Construct actual effective coordinate sections and prove that support complements equal preimages of standard coordinate opens.", "Actual regular stalk equations prove effectivity; the unit criterion identifies the precise support. Affine coordinate nonvanishing loci cover, constructing CartierAffineSectionCover rather than assuming it.", ["Actual regular stalk equations prove effectivity; the unit criterion identifies the precise support. Affine coordinate nonvanishing loci cover, constructing CartierAffineSectionCover rather than assuming it."], [["Coordinate zero loci and affine nonvanishing cover", "Actual regular stalk equations prove effectivity; the unit criterion identifies the precise support. Affine coordinate nonvanishing loci cover, constructing CartierAffineSectionCover rather than assuming it."]]];

entries.projgenerators=["Equal-degree generators automatically give a cover", "Positive equal-degree generators cover actual Proj; choose coordinates at actual points and construct Cartier section data.", "Use the actual irrelevant ideal and Proj standard-open cover theorem. Polynomial induction separately proves that standard variables generate the whole ring over its genuine degree-zero subring.", ["Use the actual irrelevant ideal and Proj standard-open cover theorem. Polynomial induction separately proves that standard variables generate the whole ring over its genuine degree-zero subring."], [["Equal-degree generators automatically give a cover", "Use the actual irrelevant ideal and Proj standard-open cover theorem. Polynomial induction separately proves that standard variables generate the whole ring over its genuine degree-zero subring."]]];
entries.projectivesections=["Relative projective space: actual O(1) data constructed", "An actual standard projective-space closed embedding constructs the Cartier divisor, effective coordinate sections and affine nonvanishing loci covering X.", "All coordinate geometry is an output. Standard variables generate the polynomial ring over its degree-zero subring; actual Proj opens, ratio stalk units and section germs construct the atlas. The genuine unit criterion identifies effective coordinate zero loci and their affine complements. No Cartier, section, effectivity, support identity, positivity or cover input.", ["Actual integral X and closed embedding into Proj R[T\u2080,\u2026,T\u2099].", "Output: actual Cartier O(1) atlas and all effective coordinate-section geometry."], [["Actual standard generators", "Polynomial induction proves generation over the degree-zero subring."], ["Actual coordinate-cover construction", "Construct homogeneous equations, stalk units, effectivity and exact supports."]]];
entries.antiample=["Existence of E: projective construction verified", "Over an affine normal birational base, an actual projective closed embedding constructs effective Cartier E covering every exceptional prime, with strictly negative degree on closed contracted complete curves.", "Actual Proj coordinates construct O(1) section geometry. A complete curve cannot lie in an affine nonvanishing locus, giving genuine positive degree. Negate and clear denominators to get effective E; actual zero-coefficient curves exclude zero exceptional coefficients. Effectivity, exceptional coverage and negative degree are outputs. No A, E, section-cover or numerical positivity witness is supplied. This theorem is over an affine base; general-base gluing is separate.", ["Algebraically closed field of arbitrary characteristic; normal integral X,Y, affine Y, compact X and proper birational f.", "Actual standard projective-space closed embedding.", "E effectivity, positive exceptional coefficients and negative actual contracted-curve degree are outputs."], [["Construct O(1)", "Actual homogeneous coordinates give Cartier sections and affine nonvanishing cover."], ["Actual positive degree and negation", "A complete curve meets an effective coordinate zero divisor, proving positive degree."], ["Denominators and exceptional coverage", "An effective principal twist and an actual zero-coefficient curve give the contradiction."], ["Complete E existence theorem", "The actual projective embedding directly yields all properties of E."]]];
entries.intersection=["Actual intersection and projective-coordinate positivity: verified", "Relative nefness tests actual contracted complete curves. Constructed projective coordinates and affine-open geometry prove positive degree of O(1).", "Actual Cartier and real intersections, normalization, effective signs, support positivity and relative nef signs are proved. Projective coordinates now construct actual section data, with no supplied section-cover witness. A complete curve meets an effective coordinate zero divisor, giving positive degree. There is no numerical positivity hypothesis.", ["Actual complete curves and constructed Cartier coordinate divisors.", "\u2212D f-nef tests actual curves contracted by f.", "Genuine positive O(1) degree follows from constructed projective sections and affine nonvanishing loci."], [["Relative nef definition", "Test actual contracted complete curves only."], ["Actual coordinate data", "Construct section-cover data from a standard projective-space closed embedding."], ["Actual geometric positivity", "A complete curve meets the zero divisor; principal invariance gives positive degree."]]];
entries.core=["Projective negativity (1) over an affine base: verified", "Over an affine normal base, an actual proper birational map with a projective-space closed embedding satisfies: effective f_*D and f-nef \u2212D imply effective D.", "This is actual geometry over an affine base, with arbitrary real weights and Cartier chart indices; curves may be singular or nonnormal and characteristic is arbitrary. O(1) equations, sections, positive degree, effective E, exceptional coverage and actual curves are constructed inside the proof, not supplied. Remaining for the complete theorem: general-base affine gluing, the proper Chow reduction, and actual fiber connectedness for part (2). The complete main theorem remains explicitly open.", ["Algebraically closed field of arbitrary characteristic; normal integral X,Y, affine Y, compact X, proper birational f and finite-type base geometry.", "Actual finite Cartier family and arbitrary real weights D; actual effective f_*D and relatively nef \u2212D.", "Actual closed embedding X\u2192Proj \u0393(Y,O_Y)[T\u2080,\u2026,T\u2099]; no Cartier-section or E witness input.", "Remaining: general-base gluing, Chow reduction and actual fiber connectedness."], [["Actual projective construction", "Homogeneous coordinates construct all actual Cartier-section data."], ["Effective E and coverage", "The projective embedding constructs effective E and every positive exceptional coefficient."], ["Actual curve contradiction", "Maximum ratios, zero coefficients, contracted curves and actual intersections give the contradiction."], ["Complete first part over an affine base", "Actual real-Cartier negativity with no additional geometric witnesses."]]];
entries.effectiveexceptional=["Effective E and positive exceptional coefficients: constructed", "An actual strictly negative Cartier divisor constructs effective E with positive coefficients at every exceptional prime.", "The strictly negative input is now derived from actual projective coordinates and actual curve positivity; see the combined E existence theorem. Neither E effectivity nor exceptional coverage is an input.", ["Actual strict Cartier negativity, derived by the projective construction."], [["Construct E", "Clear denominators and exclude zero exceptional coefficients with actual contracted curves."]]];
entries.affinesectionpositive=["Affine section cover \u21d2 actual positive degree", "Actual effective linearly equivalent divisors with affine nonvanishing loci covering the scheme imply positive actual degree on closed complete integral curves.", "Choose a section nonvanishing at the curve generic point. A complete curve meets its effective zero divisor; actual support positivity and principal invariance give positive degree. Construction of this geometry from an actual standard projective-space embedding is also proved at projectivesections.", ["Actual Cartier affine-section geometry; constructed from projective coordinates."], [["Actual geometric positive degree", "The complete curve meets an effective zero divisor and principal invariance preserves degree."]]];

entries.opencartier=["Actual open restriction: divisor coefficients unchanged", "The fixed actual Cartier pullback to an open subscheme preserves integer and real Weil coefficients.", "Actual open-immersion stalk isomorphisms and preserved codimension give equal local DVR orders, then sum finite real weights. No restriction-coefficient compatibility input.", ["Actual open-immersion stalk isomorphisms and preserved codimension give equal local DVR orders, then sum finite real weights. No restriction-coefficient compatibility input."], [["Actual open restriction: divisor coefficients unchanged", "Actual open-immersion stalk isomorphisms and preserved codimension give equal local DVR orders, then sum finite real weights. No restriction-coefficient compatibility input."]]];

entries.openpush=["Restrict effectivity of actual f_*D", "After restricting the proper birational map and divisor to an actual nonempty base open, pushforward remains effective.", "Actual codimension-one isomorphisms identify pushforward and strict-transform coefficients; open stalk-order compatibility gives restricted coefficients. Other codimensions vanish by actual mapCoeff.", ["Actual codimension-one isomorphisms identify pushforward and strict-transform coefficients; open stalk-order compatibility gives restricted coefficients. Other codimensions vanish by actual mapCoeff."], [["Restrict effectivity of actual f_*D", "Actual codimension-one isomorphisms identify pushforward and strict-transform coefficients; open stalk-order compatibility gives restricted coefficients. Other codimensions vanish by actual mapCoeff."]]];

entries.opennef=["Relative nefness persists on actual base opens", "Actual real-Cartier relative nefness restricts to every nonempty target open.", "Actual complete curves remain complete through the open immersion; the actual commutative relation transports contraction. The fixed Cartier pullback normalization-intersection composition formula gives identical intersections.", ["Actual complete curves remain complete through the open immersion; the actual commutative relation transports contraction. The fixed Cartier pullback normalization-intersection composition formula gives identical intersections."], [["Relative nefness persists on actual base opens", "Actual complete curves remain complete through the open immersion; the actual commutative relation transports contraction. The fixed Cartier pullback normalization-intersection composition formula gives identical intersections."]]];

entries.relativeprojective=["Genuine relative projective embedding over the base", "Construct the actual structure map P^n_R\u2192Spec R; the closed embedding commutes with f and constructs actual Cartier section data.", "The actual degree-zero subring and coefficient C map construct the structure morphism. Projectivity contains genuine Scheme closed embeddings and the commuting equation only, with no divisor, numerical, section or negativity conclusion.", ["The actual degree-zero subring and coefficient C map construct the structure morphism. Projectivity contains genuine Scheme closed embeddings and the commuting equation only, with no divisor, numerical, section or negativity conclusion."], [["Genuine relative projective embedding over the base", "The actual degree-zero subring and coefficient C map construct the structure morphism. Projectivity contains genuine Scheme closed embeddings and the commuting equation only, with no divisor, numerical, section or negativity conclusion."]]];
entries.projective=["Projective negativity (1): general base verified", "For normal varieties over an algebraically closed field of arbitrary characteristic, an actual proper birational relatively projective f and f-nef \u2212D satisfy: effective D iff actual f_*D is effective.", "The actual real-Cartier first part is connected on a general normal base, in both directions. Relative projectivity uses genuine standard Proj closed embeddings commuting with f on actual affine base opens. Restricted coefficients, pushforward effectivity and relative nefness are proved; local O(1), sections, degree positivity, effective E, exceptional coverage and actual curves are constructed internally. No affine-base, E, section, numerical, local-effectivity or intersection-compatibility input. The proper Chow reduction and actual fiber connectedness for part (2) of the full Theorem 1.4 remain open.", ["Algebraically closed field of arbitrary characteristic; normal integral X,Y, actual proper birational f and finite-type base geometry.", "Relative projectivity: genuine standard Proj closed embeddings commuting with f on actual affine base opens.", "Arbitrary finite actual Cartier presentation with real weights D; actual f-nef \u2212D.", "Conclusion: effective D iff actual f_*D is effective. This is the projective first-part step of the full proper two-part theorem."], [["Actual affine restriction", "Cartier coefficients, pushforward effectivity and relative nefness persist."], ["Actual affine-base proof", "Actual Proj coordinates construct O(1) and all E geometry."], ["General-base gluing", "Apply the actual local theorem on an affine neighborhood of each point image; restricted coefficients agree."], ["Effectivity equivalence", "Actual pushforward preserves effectivity; geometric negativity gives the reverse implication."]]];
entries.core[2]="The actual affine-base theorem is verified, with Cartier sections, positive degree, effective E, exceptional coverage and actual curves constructed inside the proof. General normal-base gluing is also proved at the projective negativity (1) node. The full proper theorem still needs Chow reduction and actual fiber connectedness for part (2).";

entries.properfunctions=["Proper birational: descent of functions on affine opens", "For actual proper birational f over a normal base, actual function pullback is bijective on nonempty affine base opens.", "Invert the actual function-field isomorphism, prove nonnegative local orders using actual codimension-one stalk isomorphisms, and extend in the normal affine ring. No H\u2070 finiteness, direct-image equality or connectedness input.", ["Invert the actual function-field isomorphism, prove nonnegative local orders using actual codimension-one stalk isomorphisms, and extend in the normal affine ring. No H\u2070 finiteness, direct-image equality or connectedness input."], [["Proper birational: descent of functions on affine opens", "Invert the actual function-field isomorphism, prove nonnegative local orders using actual codimension-one stalk isomorphisms, and extend in the normal affine ring. No H\u2070 finiteness, direct-image equality or connectedness input."]]];

entries.structuresheaf=["Actual structure sheaf: O_Y \u2245 f_*O_X", "For a proper birational map to a normal locally Noetherian integral scheme, the actual natural structure-sheaf map is an isomorphism.", "Actual affine-basis function descent is proved; the genuine sheaf-basis isomorphism theorem glues, and the terminal empty component handles empty opens. The equality f_*O_X=O_Y is not assumed; fiber connectedness still needs proper formal functions.", ["Actual affine-basis function descent is proved; the genuine sheaf-basis isomorphism theorem glues, and the terminal empty component handles empty opens. The equality f_*O_X=O_Y is not assumed; fiber connectedness still needs proper formal functions."], [["Actual structure sheaf: O_Y \u2245 f_*O_X", "Actual affine-basis function descent is proved; the genuine sheaf-basis isomorphism theorem glues, and the terminal empty component handles empty opens. The equality f_*O_X=O_Y is not assumed; fiber connectedness still needs proper formal functions."]]];

entries.propersections=["Every actual base open: unique descent of functions", "Actual pullback \u0393(Y,U)\u2192\u0393(X,f\u207b\u00b9U) is bijective for every open U, including nonaffine and empty opens.", "Apply the actual sheaf-isomorphism forgetful functor and genuine natural-transformation components to obtain IsIso(f.app U), then use concrete-category bijectivity. No abstract descent map is supplied.", ["Apply the actual sheaf-isomorphism forgetful functor and genuine natural-transformation components to obtain IsIso(f.app U), then use concrete-category bijectivity. No abstract descent map is supplied."], [["Every actual base open: unique descent of functions", "Apply the actual sheaf-isomorphism forgetful functor and genuine natural-transformation components to obtain IsIso(f.app U), then use concrete-category bijectivity. No abstract descent map is supplied."]]];

entries.schemeidempotents=["Actual schemes: clopen decompositions and idempotents", "An actual nontrivial clopen decomposition constructs a nontrivial idempotent in the genuine global section ring; only trivial idempotents imply actual connectedness.", "Genuine structure-sheaf gluing on disjoint opens gives \u0393(X,U\u222aV)\u2245\u0393(X,U)\u00d7\u0393(X,V). Construct and verify the inverse image of (1,0). This does not assert that actual proper-fiber section rings already have only trivial idempotents.", ["Genuine structure-sheaf gluing on disjoint opens gives \u0393(X,U\u222aV)\u2245\u0393(X,U)\u00d7\u0393(X,V). Construct and verify the inverse image of (1,0). This does not assert that actual proper-fiber section rings already have only trivial idempotents."], [["Actual schemes: clopen decompositions and idempotents", "Genuine structure-sheaf gluing on disjoint opens gives \u0393(X,U\u222aV)\u2245\u0393(X,U)\u00d7\u0393(X,V). Construct and verify the inverse image of (1,0). This does not assert that actual proper-fiber section rings already have only trivial idempotents."]]];

entries.clopencharacteristic=["Actual clopen characteristic sections and pullback", "The unique characteristic regular function of actual clopen S has germs 1 on S and 0 off S; genuine pullback preserves it.", "Actual sheaf gluing constructs the section; germ uniqueness proves idempotency and genuine pullback compatibility. No idempotent-compatibility equation is an input.", ["Actual sheaf gluing constructs the section; germ uniqueness proves idempotency and genuine pullback compatibility. No idempotent-compatibility equation is an input."], [["Actual clopen characteristic sections and pullback", "Actual sheaf gluing constructs the section; germ uniqueness proves idempotency and genuine pullback compatibility. No idempotent-compatibility equation is an input."]]];

entries.infinitesimals=["Actual infinitesimal thickenings: compatible nontrivial idempotents", "A nontrivial clopen decomposition of an actual closed subscheme constructs a nontrivial idempotent in the function inverse limit of actual ideal-power thickenings.", "Construct actual I^(n+1) subschemes, their homeomorphisms with the original support, genuine inclusions and the function inverse-limit ring. Characteristic pullback proves compatibility at all orders. The proper nonaffine formal-functions comparison is not proved here.", ["Construct actual I^(n+1) subschemes, their homeomorphisms with the original support, genuine inclusions and the function inverse-limit ring. Characteristic pullback proves compatibility at all orders. The proper nonaffine formal-functions comparison is not proved here."], [["Actual infinitesimal thickenings: compatible nontrivial idempotents", "Construct actual I^(n+1) subschemes, their homeomorphisms with the original support, genuine inclusions and the function inverse-limit ring. Characteristic pullback proves compatibility at all orders. The proper nonaffine formal-functions comparison is not proved here."]]];

entries.affinethickening=["Actual affine thickening quotients and transitions", "On actual affine X, \u0393(X_n,O)\u2245\u0393(X,O)/I^(n+1), and genuine thickening restrictions equal quotient transition maps.", "Use the actual ideal-subscheme structure-sheaf quotient isomorphism and genuine inclusion composition to prove transition compatibility. The source X must be affine; affineness of the base alone is insufficient.", ["Use the actual ideal-subscheme structure-sheaf quotient isomorphism and genuine inclusion composition to prove transition compatibility. The source X must be affine; affineness of the base alone is insufficient."], [["Actual affine thickening quotients and transitions", "Use the actual ideal-subscheme structure-sheaf quotient isomorphism and genuine inclusion composition to prove transition compatibility. The source X must be affine; affineness of the base alone is insufficient."]]];

entries.affineformalfunctions=["Affine formal functions: actual completion comparison", "For actual affine X, the canonical map from actual adic completion to the actual inverse limit of power-thickening functions is bijective.", "Actual quotient isomorphisms construct the canonical comparison; the zero-order quotient is zero, and compatible families recover all other orders, proving injectivity and surjectivity. No abstract comparison or compatibility input. This is the affine-source theorem only: the proper nonaffine global comparison and full negativity lemma remain open.", ["Actual quotient isomorphisms construct the canonical comparison; the zero-order quotient is zero, and compatible families recover all other orders, proving injectivity and surjectivity. No abstract comparison or compatibility input. This is the affine-source theorem only: the proper nonaffine global comparison and full negativity lemma remain open."], [["Affine formal functions: actual completion comparison", "Actual quotient isomorphisms construct the canonical comparison; the zero-order quotient is zero, and compatible families recover all other orders, proving injectivity and surjectivity. No abstract comparison or compatibility input. This is the affine-source theorem only: the proper nonaffine global comparison and full negativity lemma remain open."]]];
entries.connected=["Actual proper-fiber connectedness: global formal functions open", "Actual f_*O_X=O_Y and compatible idempotents on genuine thickenings are proved. The proper nonaffine global formal-functions comparison remains before concluding actual fiber connectedness.", "The actual natural structure-sheaf isomorphism for proper birational maps to normal bases and function descent on every open are proved. Actual clopen characteristic sections, genuine pullback compatibility and compatible nontrivial idempotents on actual ideal-power thickenings are proved. The genuine affine-source adic comparison is proved, but a proper source is generally nonaffine, so this does not replace global formal functions. Remaining: over the local base R=O_Y,y, the actual comparison R\u0302\u2245lim_n \u0393(X\u00d7_Spec R Spec(R/m^(n+1)),O), and identification with the actual fiber. This node and the full theorem remain open. High-dimensional crossing-curve selection is complete.", ["Proved: actual natural O_Y\u2192f_*O_X isomorphism and actual function bijectivity on every open.", "Proved: actual clopen characteristic sections, pullback compatibility and a nontrivial idempotent in the function inverse limit of genuine ideal-power thickenings.", "Proved: the canonical adic comparison when the source X is affine.", "Open: proper nonaffine global formal functions R\u0302\u2245lim_n \u0393(X_n,O_Xn), and the actual fiber identification."], [["Actual structure-sheaf isomorphism: verified", "Codimension-one isomorphisms and normal affine extension prove function descent, then genuine sheaf-basis gluing."], ["Compatible actual thickening idempotents: verified", "Actual powers have the same closed support; genuine characteristic pullback proves compatibility."], ["Affine formal functions: verified", "The actual affine-source completion comparison is bijective; this is not the proper nonaffine theorem."], ["Proper global formal functions: open", "Prove the canonical comparison between R\u0302 and the actual infinitesimal-fiber function inverse limit over the local base, then identify the actual fiber."], ["Local-ring contradiction: verified", "A complete local ring has no nontrivial idempotent, giving connectedness."]]];

entries.projchartquot=["Actual projective affine chart: finite-type quotient", "For a commutative ring R and a finite-type R-algebra B, construct a surjective R-algebra map from an actual standard D\u208a(X\u2080) chart ring to B.", "For a commutative ring R and a finite-type R-algebra B, construct a surjective R-algebra map from an actual standard D\u208a(X\u2080) chart ring to B. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem.", ["For a commutative ring R and a finite-type R-algebra B, construct a surjective R-algebra map from an actual standard D\u208a(X\u2080) chart ring to B."], [["Actual projective affine chart: finite-type quotient", "For a commutative ring R and a finite-type R-algebra B, construct a surjective R-algebra map from an actual standard D\u208a(X\u2080) chart ring to B. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem."]]];

entries.affineprojimmersion=["Affine finite-type map: actual projective immersion", "For actual affine X,Y and locally finite-type f:X\u2192Y, construct n and an actual immersion X\u2192P\u207f_\u0393(Y) over f. This immersion is not asserted closed.", "For actual affine X,Y and locally finite-type f:X\u2192Y, construct n and an actual immersion X\u2192P\u207f_\u0393(Y) over f. This immersion is not asserted closed. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem.", ["For actual affine X,Y and locally finite-type f:X\u2192Y, construct n and an actual immersion X\u2192P\u207f_\u0393(Y) over f. This immersion is not asserted closed."], [["Affine finite-type map: actual projective immersion", "For actual affine X,Y and locally finite-type f:X\u2192Y, construct n and an actual immersion X\u2192P\u207f_\u0393(Y) over f. This immersion is not asserted closed. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem."]]];

entries.standardprojproper=["Standard relative projective space: actual properness", "For every commutative ring R and n, actual Proj(R[X\u2080,\u2026,X\u2099])\u2192Spec R is proper; the degree-zero ring isomorphism with R is constructed.", "For every commutative ring R and n, actual Proj(R[X\u2080,\u2026,X\u2099])\u2192Spec R is proper; the degree-zero ring isomorphism with R is constructed. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem.", ["For every commutative ring R and n, actual Proj(R[X\u2080,\u2026,X\u2099])\u2192Spec R is proper; the degree-zero ring isomorphism with R is constructed."], [["Standard relative projective space: actual properness", "For every commutative ring R and n, actual Proj(R[X\u2080,\u2026,X\u2099])\u2192Spec R is proper; the degree-zero ring isomorphism with R is constructed. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem."]]];

entries.hartshornecover=["Hartshorne: finite affine cover and common open", "For integral quasi-compact X, affine Y and actual locally finite-type f, construct a finite nonempty affine cover, actual projective immersions and a nonempty common open.", "For integral quasi-compact X, affine Y and actual locally finite-type f, construct a finite nonempty affine cover, actual projective immersions and a nonempty common open. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem.", ["For integral quasi-compact X, affine Y and actual locally finite-type f, construct a finite nonempty affine cover, actual projective immersions and a nonempty common open."], [["Hartshorne: finite affine cover and common open", "For integral quasi-compact X, affine Y and actual locally finite-type f, construct a finite nonempty affine cover, actual projective immersions and a nonempty common open. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem."]]];

entries.hartshornefinite=["Hartshorne graph: finite second projection", "In an actual proper graph construction for integral Noetherian X, local projective immersions agree with the common rational map. Construct integral Z, proper birational surjective \u03c0:Z\u2192X and finite q:Z\u2192P.", "In an actual proper graph construction for integral Noetherian X, local projective immersions agree with the common rational map. Construct integral Z, proper birational surjective \u03c0:Z\u2192X and finite q:Z\u2192P. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem.", ["In an actual proper graph construction for integral Noetherian X, local projective immersions agree with the common rational map. Construct integral Z, proper birational surjective \u03c0:Z\u2192X and finite q:Z\u2192P."], [["Hartshorne graph: finite second projection", "In an actual proper graph construction for integral Noetherian X, local projective immersions agree with the common rational map. Construct integral Z, proper birational surjective \u03c0:Z\u2192X and finite q:Z\u2192P. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem."]]];

entries.affineproductcharts=["Actual fiber product: affine charts", "For affine S, arbitrary X\u2192S,Y\u2192S and affine opens U\u2282X,V\u2282Y, actual pr\u2081\u207b\u00b9U\u2229pr\u2082\u207b\u00b9V in X\u00d7_S Y is affine.", "For affine S, arbitrary X\u2192S,Y\u2192S and affine opens U\u2282X,V\u2282Y, actual pr\u2081\u207b\u00b9U\u2229pr\u2082\u207b\u00b9V in X\u00d7_S Y is affine. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem.", ["For affine S, arbitrary X\u2192S,Y\u2192S and affine opens U\u2282X,V\u2282Y, actual pr\u2081\u207b\u00b9U\u2229pr\u2082\u207b\u00b9V in X\u00d7_S Y is affine."], [["Actual fiber product: affine charts", "For affine S, arbitrary X\u2192S,Y\u2192S and affine opens U\u2282X,V\u2282Y, actual pr\u2081\u207b\u00b9U\u2229pr\u2082\u207b\u00b9V in X\u00d7_S Y is affine. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem."]]];

entries.properproduct=["Actual finite relative product: construction and affine charts", "For finitely many actual proper T\u1d62\u2192S, construct the actual relative product P\u2192S, projections and universal property. For affine S, simultaneous inverse images of affine opens are affine.", "For finitely many actual proper T\u1d62\u2192S, construct the actual relative product P\u2192S, projections and universal property. For affine S, simultaneous inverse images of affine opens are affine. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem.", ["For finitely many actual proper T\u1d62\u2192S, construct the actual relative product P\u2192S, projections and universal property. For affine S, simultaneous inverse images of affine opens are affine."], [["Actual finite relative product: construction and affine charts", "For finitely many actual proper T\u1d62\u2192S, construct the actual relative product P\u2192S, projections and universal property. For affine S, simultaneous inverse images of affine opens are affine. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem."]]];

entries.hartshornemodification=["Hartshorne: actual finite-product modification", "For integral locally Noetherian X, affine Y and actual proper f, internally construct the cover, common rational map and graph, producing integral Z, proper birational surjective \u03c0:Z\u2192X and finite q to an actual projective product.", "For integral locally Noetherian X, affine Y and actual proper f, internally construct the cover, common rational map and graph, producing integral Z, proper birational surjective \u03c0:Z\u2192X and finite q to an actual projective product. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem.", ["For integral locally Noetherian X, affine Y and actual proper f, internally construct the cover, common rational map and graph, producing integral Z, proper birational surjective \u03c0:Z\u2192X and finite q to an actual projective product."], [["Hartshorne: actual finite-product modification", "For integral locally Noetherian X, affine Y and actual proper f, internally construct the cover, common rational map and graph, producing integral Z, proper birational surjective \u03c0:Z\u2192X and finite q to an actual projective product. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem."]]];

entries.birationalcomp=["Actual birational morphisms: composition", "The composite of actual separated locally finite-type birational morphisms between integral schemes is birational. Actual nonempty isomorphism opens are constructed from generic stalk isomorphisms.", "The composite of actual separated locally finite-type birational morphisms between integral schemes is birational. Actual nonempty isomorphism opens are constructed from generic stalk isomorphisms. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem.", ["The composite of actual separated locally finite-type birational morphisms between integral schemes is birational. Actual nonempty isomorphism opens are constructed from generic stalk isomorphisms."], [["Actual birational morphisms: composition", "The composite of actual separated locally finite-type birational morphisms between integral schemes is birational. Actual nonempty isomorphism opens are constructed from generic stalk isomorphisms. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem."]]];

entries.normalhartshorne=["Hartshorne: actual normal modification", "Over an algebraically closed field of arbitrary characteristic, for integral locally Noetherian X, affine finite-type Y and proper f, construct normal integral locally Noetherian N, proper birational surjective \u03c0:N\u2192X and a finite map to an actual projective product.", "Over an algebraically closed field of arbitrary characteristic, for integral locally Noetherian X, affine finite-type Y and proper f, construct normal integral locally Noetherian N, proper birational surjective \u03c0:N\u2192X and a finite map to an actual projective product. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem.", ["Over an algebraically closed field of arbitrary characteristic, for integral locally Noetherian X, affine finite-type Y and proper f, construct normal integral locally Noetherian N, proper birational surjective \u03c0:N\u2192X and a finite map to an actual projective product."], [["Hartshorne: actual normal modification", "Over an algebraically closed field of arbitrary characteristic, for integral locally Noetherian X, affine finite-type Y and proper f, construct normal integral locally Noetherian N, proper birational surjective \u03c0:N\u2192X and a finite map to an actual projective product. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem."]]];

entries.productcartier=["Actual projective product: Cartier section cover", "For integral X with actual finite q:X\u2192P and the proved affine product-chart property, construct an actual Cartier atlas, effective sections, support identities and affine nonvanishing cover.", "For integral X with actual finite q:X\u2192P and the proved affine product-chart property, construct an actual Cartier atlas, effective sections, support identities and affine nonvanishing cover. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem.", ["For integral X with actual finite q:X\u2192P and the proved affine product-chart property, construct an actual Cartier atlas, effective sections, support identities and affine nonvanishing cover."], [["Actual projective product: Cartier section cover", "For integral X with actual finite q:X\u2192P and the proved affine product-chart property, construct an actual Cartier atlas, effective sections, support identities and affine nonvanishing cover. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem."]]];

entries.canonicalpushpull=["The same canonical actual pullback: \u03c0_*\u03c0*D=D", "For proper birational \u03c0 between normal integral locally Noetherian schemes and any finite real Cartier sum D, the same canonical pullback used for intersection and nefness satisfies actual Weil-cycle \u03c0_*\u03c0*D=D.", "For proper birational \u03c0 between normal integral locally Noetherian schemes and any finite real Cartier sum D, the same canonical pullback used for intersection and nefness satisfies actual Weil-cycle \u03c0_*\u03c0*D=D. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem.", ["For proper birational \u03c0 between normal integral locally Noetherian schemes and any finite real Cartier sum D, the same canonical pullback used for intersection and nefness satisfies actual Weil-cycle \u03c0_*\u03c0*D=D."], [["The same canonical actual pullback: \u03c0_*\u03c0*D=D", "For proper birational \u03c0 between normal integral locally Noetherian schemes and any finite real Cartier sum D, the same canonical pullback used for intersection and nefness satisfies actual Weil-cycle \u03c0_*\u03c0*D=D. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem."]]];

entries.birationalcyclecomp=["Actual birational Weil pushforward: composition", "For proper birational p:Z\u2192X,f:X\u2192Y with normal integral locally Noetherian X,Y, every actual Weil cycle E satisfies (f\u2218p)_*E=f_*(p_*E); the codimension-one property is derived.", "For proper birational p:Z\u2192X,f:X\u2192Y with normal integral locally Noetherian X,Y, every actual Weil cycle E satisfies (f\u2218p)_*E=f_*(p_*E); the codimension-one property is derived. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem.", ["For proper birational p:Z\u2192X,f:X\u2192Y with normal integral locally Noetherian X,Y, every actual Weil cycle E satisfies (f\u2218p)_*E=f_*(p_*E); the codimension-one property is derived."], [["Actual birational Weil pushforward: composition", "For proper birational p:Z\u2192X,f:X\u2192Y with normal integral locally Noetherian X,Y, every actual Weil cycle E satisfies (f\u2218p)_*E=f_*(p_*E); the codimension-one property is derived. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem."]]];

entries.chow=["Hartshorne normal modification and actual sections: verified", "Over an algebraically closed field of arbitrary characteristic, for affine finite-type Y, integral locally Noetherian X and proper f, construct actual normal integral N, proper birational surjective \u03c0:N\u2192X and an actual Cartier affine-section cover on N.", "Over an algebraically closed field of arbitrary characteristic, for affine finite-type Y, integral locally Noetherian X and proper f, construct actual normal integral N, proper birational surjective \u03c0:N\u2192X and an actual Cartier affine-section cover on N. Hartshorne\u2019s actual finite graph is normalized finitely; products of actual coordinate ratios construct the section geometry. All modification and section inputs needed for negativity (1) are proved. This does not assert a separately formalized Segre closed embedding or the general Chow lemma. Actual fiber connectedness remains for the full two-part theorem.", ["Over an algebraically closed field of arbitrary characteristic, for affine finite-type Y, integral locally Noetherian X and proper f, construct actual normal integral N, proper birational surjective \u03c0:N\u2192X and an actual Cartier affine-section cover on N."], [["Hartshorne normal modification and actual sections: verified", "Over an algebraically closed field of arbitrary characteristic, for affine finite-type Y, integral locally Noetherian X and proper f, construct actual normal integral N, proper birational surjective \u03c0:N\u2192X and an actual Cartier affine-section cover on N. Hartshorne\u2019s actual finite graph is normalized finitely; products of actual coordinate ratios construct the section geometry. All modification and section inputs needed for negativity (1) are proved. This does not assert a separately formalized Segre closed embedding or the general Chow lemma. Actual fiber connectedness remains for the full two-part theorem."]]];

entries.properaffine=["Proper negativity (1): affine base verified", "Over an algebraically closed field of arbitrary characteristic, let X,Y be normal integral locally Noetherian, Y affine finite type and f proper birational. For any finite real Cartier sum D, if \u2212D is f-nef and actual f_*D\u22650, then D\u22650.", "Over an algebraically closed field of arbitrary characteristic, let X,Y be normal integral locally Noetherian, Y affine finite type and f proper birational. For any finite real Cartier sum D, if \u2212D is f-nef and actual f_*D\u22650, then D\u22650. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem.", ["Over an algebraically closed field of arbitrary characteristic, let X,Y be normal integral locally Noetherian, Y affine finite type and f proper birational. For any finite real Cartier sum D, if \u2212D is f-nef and actual f_*D\u22650, then D\u22650."], [["Proper negativity (1): affine base verified", "Over an algebraically closed field of arbitrary characteristic, let X,Y be normal integral locally Noetherian, Y affine finite type and f proper birational. For any finite real Cartier sum D, if \u2212D is f-nef and actual f_*D\u22650, then D\u22650. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem."]]];

entries.properone=["Proper negativity (1): general base verified", "Over an algebraically closed field of arbitrary characteristic, let X,Y be normal integral locally Noetherian, Y finite type and f proper birational. For any finite real Cartier sum D, if \u2212D is f-nef and actual f_*D\u22650, then D\u22650. Projectivity is not required.", "Over an algebraically closed field of arbitrary characteristic, let X,Y be normal integral locally Noetherian, Y finite type and f proper birational. For any finite real Cartier sum D, if \u2212D is f-nef and actual f_*D\u22650, then D\u22650. Projectivity is not required. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem.", ["Over an algebraically closed field of arbitrary characteristic, let X,Y be normal integral locally Noetherian, Y finite type and f proper birational. For any finite real Cartier sum D, if \u2212D is f-nef and actual f_*D\u22650, then D\u22650. Projectivity is not required."], [["Proper negativity (1): general base verified", "Over an algebraically closed field of arbitrary characteristic, let X,Y be normal integral locally Noetherian, Y finite type and f proper birational. For any finite real Cartier sum D, if \u2212D is f-nef and actual f_*D\u22650, then D\u22650. Projectivity is not required. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem."]]];

entries.properiff=["Proper negativity (1): full equivalence verified", "For normal varieties over an algebraically closed field of arbitrary characteristic, proper birational f and a finite real Cartier sum D with \u2212D f-nef, D\u22650 iff actual f_*D\u22650. Conclusion (1) is complete; the independent fiber-support conclusion (2) remains open.", "For normal varieties over an algebraically closed field of arbitrary characteristic, proper birational f and a finite real Cartier sum D with \u2212D f-nef, D\u22650 iff actual f_*D\u22650. Conclusion (1) is complete; the independent fiber-support conclusion (2) remains open. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem.", ["For normal varieties over an algebraically closed field of arbitrary characteristic, proper birational f and a finite real Cartier sum D with \u2212D f-nef, D\u22650 iff actual f_*D\u22650. Conclusion (1) is complete; the independent fiber-support conclusion (2) remains open."], [["Proper negativity (1): full equivalence verified", "For normal varieties over an algebraically closed field of arbitrary characteristic, proper birational f and a finite real Cartier sum D with \u2212D f-nef, D\u22650 iff actual f_*D\u22650. Conclusion (1) is complete; the independent fiber-support conclusion (2) remains open. All stated ordinary hypotheses apply. This declaration is compiled and kernel-audited; actual fiber connectedness remains for conclusion (2) of the complete theorem."]]];
entries.proper=["Proper negativity lemma: conclusion (1) complete", "The final two-part target: actual proper effectivity equivalence (1) is proved; actual fiber-support dichotomy (2) remains open.", "Conclusion (1) is fully proved, with no projectivity, modification, E, section or curve input. Actual support dichotomy on already connected proper schemes is proved, but actual proper birational fiber connectedness remains. The complete Theorem 1.4 stays open.", ["Proved: actual proper negativity (1), D\u22650 iff actual f_*D\u22650.", "Open: actual proper birational fiber connectedness and the final connection for conclusion (2)."], [["Conclusion (1): verified", "Actual Hartshorne normal modification, coordinate sections, intersection, nef pullback and cycle descent are connected."], ["Conclusion (2): still open", "Prove actual proper birational fiber connectedness, then apply the verified actual support dichotomy."]]];
entries.properreduce[2]="This node retains the abstract descent combination. Its actual modification, nef, push-pull and effectivity inputs for conclusion (1) are all proved by the separate properiff node. Actual fiber connectedness remains for conclusion (2).";
entries.projective[2]+=" Proper conclusion (1) is now proved by properiff; actual fiber connectedness remains for conclusion (2).";

entries.properformalfunctions=["Proper nonaffine formal-functions bijectivity: open", "For proper birational f:X\u2192Y with normal base, prove the constructed canonical map \u0393(U)\u0302_m \u2192 lim\u2099 \u0393(X_U\u00d7_U U\u2099,O) bijective for every actual affine neighborhood U and closed y\u2208U. X_U is generally nonaffine.", "The actual comparison map, relative thickenings and evaluations are constructed. Proper nonaffine bijectivity remains open; the affine-source theorem does not establish it. This is the Hartshorne III.11 formal-functions step, with no new Lean axiom.", ["Open: ActualClosedFiberFormalFunctions f, actualRelativeFormalFunctionsMap bijective at closed points of each actual affine neighborhood."], [["Prove bijectivity", "The actual map is constructed; prove injectivity and surjectivity for proper birational f over a normal base."]]];
entries.relativeformalmap=["Actual relative formal functions: constructed map", "For affine Y, possibly nonaffine X and an ideal sheaf I on Y, construct the canonical ring map from the I-adic completion of \u0393(Y) to compatible actual functions on X\u00d7_Y Y\u2099. Prove its evaluations and constant pullbacks. Bijectivity is not proved.", "For affine Y, possibly nonaffine X and an ideal sheaf I on Y, construct the canonical ring map from the I-adic completion of \u0393(Y) to compatible actual functions on X\u00d7_Y Y\u2099. Prove its evaluations and constant pullbacks. Bijectivity is not proved. This actual declaration is compiled and kernel-audited under its stated ordinary theorem conditions.", ["For affine Y, possibly nonaffine X and an ideal sheaf I on Y, construct the canonical ring map from the I-adic completion of \u0393(Y) to compatible actual functions on X\u00d7_Y Y\u2099. Prove its evaluations and constant pullbacks. Bijectivity is not proved."], [["Actual relative formal functions: constructed map", "For affine Y, possibly nonaffine X and an ideal sheaf I on Y, construct the canonical ring map from the I-adic completion of \u0393(Y) to compatible actual functions on X\u00d7_Y Y\u2099. Prove its evaluations and constant pullbacks. Bijectivity is not proved. This actual declaration is compiled and kernel-audited under its stated ordinary theorem conditions."]]];
entries.relativeidem=["Actual relative thickenings: compatible idempotents", "For any actual f:X\u2192Y and ideal sheaf I, a nontrivial clopen decomposition of the actual closed subscheme defined by I\u00b7O_X constructs a compatible nontrivial idempotent in actual relative thickening functions. X need not be affine.", "For any actual f:X\u2192Y and ideal sheaf I, a nontrivial clopen decomposition of the actual closed subscheme defined by I\u00b7O_X constructs a compatible nontrivial idempotent in actual relative thickening functions. X need not be affine. This actual declaration is compiled and kernel-audited under its stated ordinary theorem conditions.", ["For any actual f:X\u2192Y and ideal sheaf I, a nontrivial clopen decomposition of the actual closed subscheme defined by I\u00b7O_X constructs a compatible nontrivial idempotent in actual relative thickening functions. X need not be affine."], [["Actual relative thickenings: compatible idempotents", "For any actual f:X\u2192Y and ideal sheaf I, a nontrivial clopen decomposition of the actual closed subscheme defined by I\u00b7O_X constructs a compatible nontrivial idempotent in actual relative thickening functions. X need not be affine. This actual declaration is compiled and kernel-audited under its stated ordinary theorem conditions."]]];
entries.closedpointcompletion=["Actual closed-point fiber ideal and local completion", "For affine locally Noetherian Y and closed y, the actual point-embedding kernel is supported on {y}, its top ideal is maximal and its completion is local. The original affine coordinate ring need not be local.", "For affine locally Noetherian Y and closed y, the actual point-embedding kernel is supported on {y}, its top ideal is maximal and its completion is local. The original affine coordinate ring need not be local. This actual declaration is compiled and kernel-audited under its stated ordinary theorem conditions.", ["For affine locally Noetherian Y and closed y, the actual point-embedding kernel is supported on {y}, its top ideal is maximal and its completion is local. The original affine coordinate ring need not be local."], [["Actual closed-point fiber ideal and local completion", "For affine locally Noetherian Y and closed y, the actual point-embedding kernel is supported on {y}, its top ideal is maximal and its completion is local. The original affine coordinate ring need not be local. This actual declaration is compiled and kernel-audited under its stated ordinary theorem conditions."]]];
entries.closedfiberidem=["Actual closed-point fiber: nontrivial idempotent", "A nontrivial clopen decomposition of the actual closed-point fiber f\u207b\u00b9(y) yields a nontrivial idempotent in its actual relative thickening section limit. The fiber-to-ideal-subscheme homeomorphism is constructed internally.", "A nontrivial clopen decomposition of the actual closed-point fiber f\u207b\u00b9(y) yields a nontrivial idempotent in its actual relative thickening section limit. The fiber-to-ideal-subscheme homeomorphism is constructed internally. This actual declaration is compiled and kernel-audited under its stated ordinary theorem conditions.", ["A nontrivial clopen decomposition of the actual closed-point fiber f\u207b\u00b9(y) yields a nontrivial idempotent in its actual relative thickening section limit. The fiber-to-ideal-subscheme homeomorphism is constructed internally."], [["Actual closed-point fiber: nontrivial idempotent", "A nontrivial clopen decomposition of the actual closed-point fiber f\u207b\u00b9(y) yields a nontrivial idempotent in its actual relative thickening section limit. The fiber-to-ideal-subscheme homeomorphism is constructed internally. This actual declaration is compiled and kernel-audited under its stated ordinary theorem conditions."]]];
entries.relativeformalconnected=["Closed-fiber connectedness: formal-functions condition", "For affine locally Noetherian Y, surjective f and closed y, bijectivity of the constructed actual comparison implies connectedness of the actual fiber f\u207b\u00b9(y). Bijectivity hff is an explicit unproved input.", "For affine locally Noetherian Y, surjective f and closed y, bijectivity of the constructed actual comparison implies connectedness of the actual fiber f\u207b\u00b9(y). Bijectivity hff is an explicit unproved input. This declaration is compiled and kernel-audited as the stated conditional theorem; its open geometric input is not removed.", ["For affine locally Noetherian Y, surjective f and closed y, bijectivity of the constructed actual comparison implies connectedness of the actual fiber f\u207b\u00b9(y). Bijectivity hff is an explicit unproved input."], [["Closed-fiber connectedness: formal-functions condition", "For affine locally Noetherian Y, surjective f and closed y, bijectivity of the constructed actual comparison implies connectedness of the actual fiber f\u207b\u00b9(y). Bijectivity hff is an explicit unproved input. This declaration is compiled and kernel-audited as the stated conditional theorem; its open geometric input is not removed."]]];
entries.constructibleclosed=["Noetherian Jacobson: constructible sets contain closed points", "Every nonempty constructible subset of a Noetherian Jacobson space contains a point closed in the entire space, by actual constructible-set induction and closed-point density in locally closed subsets.", "Every nonempty constructible subset of a Noetherian Jacobson space contains a point closed in the entire space, by actual constructible-set induction and closed-point density in locally closed subsets. This actual declaration is compiled and kernel-audited under its stated ordinary theorem conditions.", ["Every nonempty constructible subset of a Noetherian Jacobson space contains a point closed in the entire space, by actual constructible-set induction and closed-point density in locally closed subsets."], [["Noetherian Jacobson: constructible sets contain closed points", "Every nonempty constructible subset of a Noetherian Jacobson space contains a point closed in the entire space, by actual constructible-set induction and closed-point density in locally closed subsets. This actual declaration is compiled and kernel-audited under its stated ordinary theorem conditions."]]];
entries.closedfiberdetection=["Actual support dichotomy: detection at closed points", "For Noetherian X,Y, Jacobson Y, locally finite-type quasi-compact f and closed S\u2282X, all-or-none membership in S on every closed-point fiber implies it on every fiber. The proof uses actual Chevalley constructibility.", "For Noetherian X,Y, Jacobson Y, locally finite-type quasi-compact f and closed S\u2282X, all-or-none membership in S on every closed-point fiber implies it on every fiber. The proof uses actual Chevalley constructibility. This actual declaration is compiled and kernel-audited under its stated ordinary theorem conditions.", ["For Noetherian X,Y, Jacobson Y, locally finite-type quasi-compact f and closed S\u2282X, all-or-none membership in S on every closed-point fiber implies it on every fiber. The proof uses actual Chevalley constructibility."], [["Actual support dichotomy: detection at closed points", "For Noetherian X,Y, Jacobson Y, locally finite-type quasi-compact f and closed S\u2282X, all-or-none membership in S on every closed-point fiber implies it on every fiber. The proof uses actual Chevalley constructibility. This actual declaration is compiled and kernel-audited under its stated ordinary theorem conditions."]]];
entries.closedfibercomplete=["Actual closed-point fiber: proper over the ground field", "For a field k, Y locally finite type over k, proper f and closed y\u2208Y, the actual fiber f\u207b\u00b9(y) is proper over Spec k. Finiteness of the closed-point residue extension and actual base change are derived.", "For a field k, Y locally finite type over k, proper f and closed y\u2208Y, the actual fiber f\u207b\u00b9(y) is proper over Spec k. Finiteness of the closed-point residue extension and actual base change are derived. This actual declaration is compiled and kernel-audited under its stated ordinary theorem conditions.", ["For a field k, Y locally finite type over k, proper f and closed y\u2208Y, the actual fiber f\u207b\u00b9(y) is proper over Spec k. Finiteness of the closed-point residue extension and actual base change are derived."], [["Actual closed-point fiber: proper over the ground field", "For a field k, Y locally finite type over k, proper f and closed y\u2208Y, the actual fiber f\u207b\u00b9(y) is proper over Spec k. Finiteness of the closed-point residue extension and actual base change are derived. This actual declaration is compiled and kernel-audited under its stated ordinary theorem conditions."]]];
entries.propersupport=["Proper support dichotomy: only closed-fiber connectedness needed", "Over an algebraically closed field of arbitrary characteristic, for normal integral Noetherian X, Noetherian finite-type Y, proper f, effective finite real Cartier sum D and \u2212D f-nef, connected actual closed-point fibers imply that every fiber avoids or lies in Supp D. Closed-fiber connectedness remains explicit.", "Over an algebraically closed field of arbitrary characteristic, for normal integral Noetherian X, Noetherian finite-type Y, proper f, effective finite real Cartier sum D and \u2212D f-nef, connected actual closed-point fibers imply that every fiber avoids or lies in Supp D. Closed-fiber connectedness remains explicit. This declaration is compiled and kernel-audited as the stated conditional theorem; its open geometric input is not removed.", ["Over an algebraically closed field of arbitrary characteristic, for normal integral Noetherian X, Noetherian finite-type Y, proper f, effective finite real Cartier sum D and \u2212D f-nef, connected actual closed-point fibers imply that every fiber avoids or lies in Supp D. Closed-fiber connectedness remains explicit."], [["Proper support dichotomy: only closed-fiber connectedness needed", "Over an algebraically closed field of arbitrary characteristic, for normal integral Noetherian X, Noetherian finite-type Y, proper f, effective finite real Cartier sum D and \u2212D f-nef, connected actual closed-point fibers imply that every fiber avoids or lies in Supp D. Closed-fiber connectedness remains explicit. This declaration is compiled and kernel-audited as the stated conditional theorem; its open geometric input is not removed."]]];
entries.affinefiberhomeo=["Actual affine neighborhoods: fiber homeomorphism", "For actual f:X\u2192Y, open U\u2282Y and y\u2208U, construct the actual scheme-fiber homeomorphism (f|_U)\u207b\u00b9(y)\u2243f\u207b\u00b9(y) and prove equivalent connectedness, without a supplied fiber isomorphism.", "For actual f:X\u2192Y, open U\u2282Y and y\u2208U, construct the actual scheme-fiber homeomorphism (f|_U)\u207b\u00b9(y)\u2243f\u207b\u00b9(y) and prove equivalent connectedness, without a supplied fiber isomorphism. This actual declaration is compiled and kernel-audited under its stated ordinary theorem conditions.", ["For actual f:X\u2192Y, open U\u2282Y and y\u2208U, construct the actual scheme-fiber homeomorphism (f|_U)\u207b\u00b9(y)\u2243f\u207b\u00b9(y) and prove equivalent connectedness, without a supplied fiber isomorphism."], [["Actual affine neighborhoods: fiber homeomorphism", "For actual f:X\u2192Y, open U\u2282Y and y\u2208U, construct the actual scheme-fiber homeomorphism (f|_U)\u207b\u00b9(y)\u2243f\u207b\u00b9(y) and prove equivalent connectedness, without a supplied fiber isomorphism. This actual declaration is compiled and kernel-audited under its stated ordinary theorem conditions."]]];
entries.connected=["Actual closed-fiber connectedness: conditional deduction connected", "For locally Noetherian Y and actual surjective f, bijectivity of the constructed actual formal-functions comparison at closed points of every affine base neighborhood implies connected actual closed-point fibers. This bijectivity is unproved; this node is verified only conditionally.", "For locally Noetherian Y and actual surjective f, bijectivity of the constructed actual formal-functions comparison at closed points of every affine base neighborhood implies connected actual closed-point fibers. This bijectivity is unproved; this node is verified only conditionally. This declaration is compiled and kernel-audited as the stated conditional theorem; its open geometric input is not removed.", ["For locally Noetherian Y and actual surjective f, bijectivity of the constructed actual formal-functions comparison at closed points of every affine base neighborhood implies connected actual closed-point fibers. This bijectivity is unproved; this node is verified only conditionally."], [["Actual closed-fiber connectedness: conditional deduction connected", "For locally Noetherian Y and actual surjective f, bijectivity of the constructed actual formal-functions comparison at closed points of every affine base neighborhood implies connected actual closed-point fibers. This bijectivity is unproved; this node is verified only conditionally. This declaration is compiled and kernel-audited as the stated conditional theorem; its open geometric input is not removed."]]];
entries.properfullconditional=["Actual proper two-part result: single-gap conditional theorem", "For normal integral Noetherian X,Y over an algebraically closed field of arbitrary characteristic, finite-type Y, proper birational f and finite real Cartier sum D with \u2212D f-nef, the explicit unproved formal-functions bijectivity hff gives D\u22650 iff f_*D\u22650 and all-or-none fiber support for effective D. The full theorem without hff is not complete.", "For normal integral Noetherian X,Y over an algebraically closed field of arbitrary characteristic, finite-type Y, proper birational f and finite real Cartier sum D with \u2212D f-nef, the explicit unproved formal-functions bijectivity hff gives D\u22650 iff f_*D\u22650 and all-or-none fiber support for effective D. The full theorem without hff is not complete. This declaration is compiled and kernel-audited as the stated conditional theorem; its open geometric input is not removed.", ["For normal integral Noetherian X,Y over an algebraically closed field of arbitrary characteristic, finite-type Y, proper birational f and finite real Cartier sum D with \u2212D f-nef, the explicit unproved formal-functions bijectivity hff gives D\u22650 iff f_*D\u22650 and all-or-none fiber support for effective D. The full theorem without hff is not complete."], [["Actual proper two-part result: single-gap conditional theorem", "For normal integral Noetherian X,Y over an algebraically closed field of arbitrary characteristic, finite-type Y, proper birational f and finite real Cartier sum D with \u2212D f-nef, the explicit unproved formal-functions bijectivity hff gives D\u22650 iff f_*D\u22650 and all-or-none fiber support for effective D. The full theorem without hff is not complete. This declaration is compiled and kernel-audited as the stated conditional theorem; its open geometric input is not removed."]]];
entries.projective2=["Fiber-support conclusion (2): formal functions still open", "For effective D with \u2212D f-nef, every actual fiber should avoid or lie in Supp D. An unconditional proof of actual proper formal-functions bijectivity remains open.", "Actual intersection, proper closed fibers, crossing curves and detection at closed points are proved. The formal-functions hypothesis hff is still unproved. Conclusion (2) remains open.", ["Open: proper nonaffine bijectivity of actualRelativeFormalFunctionsMap."], [["Remaining comparison", "Remove the unproved hff input from the connected actual two-part theorem."]]];
entries.proper[2]="Conclusion (1) is fully proved without extra geometric inputs. All subsequent deductions for conclusion (2) are connected, but the composed theorem still contains explicit hff: actual proper nonaffine formal-functions bijectivity. This hypothesis is unproved; complete Theorem 1.4 remains open.";
entries.proper[3]=["Proved: actual proper negativity (1), D≥0 iff actual f_*D≥0.","Open: prove actual proper nonaffine formal-functions bijectivity and remove hff from the composed theorem."];
